struct DaemonGatewayClock;

impl Clock for DaemonGatewayClock {
    fn now_unix(&self) -> u64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0)
    }
}

struct DaemonGatewayIds;

impl IdSource for DaemonGatewayIds {
    fn new_session_id(&self) -> d2b_gateway::DisplaySessionId {
        let mut raw = [0u8; 16];
        getrandom::getrandom(&mut raw).unwrap_or(());
        d2b_gateway::DisplaySessionId::new(format!("gw-{}", hex_bytes(&raw)))
    }

    fn new_secret(&self) -> SessionSecret {
        let mut raw = [0u8; SECRET_LEN];
        getrandom::getrandom(&mut raw).unwrap_or(());
        SessionSecret::from_bytes(raw)
    }
}

#[cfg(test)]
fn dispatch_exec_management(
    state: &ServerState,
    peer: &PeerIdentity,
    op: public_wire::ExecOp,
) -> Result<Value, TypedError> {
    if let Some(vm) = exec_op_vm(&op) {
        ensure_vm_runtime_capability(state, vm, RuntimeCapabilityGate::Exec, "exec")?;
    }
    let response = match op {
        public_wire::ExecOp::List(args) => public_wire::ExecOpResponse::List(
            exec_detached::list_as(state, &args, broker_caller_role_for_peer(peer))?,
        ),
        public_wire::ExecOp::Logs(args) => public_wire::ExecOpResponse::Logs(
            exec_detached::logs_as(state, &args, broker_caller_role_for_peer(peer))?,
        ),
        public_wire::ExecOp::Status(args) => public_wire::ExecOpResponse::Status(
            exec_detached::status_as(state, &args, broker_caller_role_for_peer(peer))?,
        ),
        public_wire::ExecOp::Kill(args) => {
            let result = exec_detached::kill_as(state, &args, broker_caller_role_for_peer(peer));
            emit_detached_kill_audit(state, peer.uid, &args.vm, result.as_ref());
            public_wire::ExecOpResponse::Kill(result?)
        }
        public_wire::ExecOp::Start(_)
        | public_wire::ExecOp::WriteStdin(_)
        | public_wire::ExecOp::ReadOutput(_)
        | public_wire::ExecOp::Signal(_)
        | public_wire::ExecOp::Resize(_)
        | public_wire::ExecOp::Wait(_)
        | public_wire::ExecOp::Close(_) => {
            return Err(TypedError::GuestControlExecFailed {
                kind: d2bd_runtime::typed_error::GuestControlExecErrorKind::Protocol,
            });
        }
    };
    Ok(d2bd_runtime::wire::exec_response(&response))
}

#[cfg(test)]
fn exec_op_vm(op: &public_wire::ExecOp) -> Option<&str> {
    match op {
        public_wire::ExecOp::Start(args) => Some(args.vm.as_str()),
        public_wire::ExecOp::List(args) => Some(args.vm.as_str()),
        public_wire::ExecOp::Logs(args) => Some(args.vm.as_str()),
        public_wire::ExecOp::Status(args) => Some(args.vm.as_str()),
        public_wire::ExecOp::Kill(args) => Some(args.vm.as_str()),
        public_wire::ExecOp::WriteStdin(_)
        | public_wire::ExecOp::ReadOutput(_)
        | public_wire::ExecOp::Signal(_)
        | public_wire::ExecOp::Resize(_)
        | public_wire::ExecOp::Wait(_)
        | public_wire::ExecOp::Close(_) => None,
    }
}

fn dispatch_keys_list(state: &ServerState) -> Result<Value, TypedError> {
    let bundle: Bundle = load_json(&state.config.artifacts.bundle_path)?;
    let manifest: ManifestV04 = load_json(&state.config.artifacts.public_manifest_path)?;
    let ssh_keygen_binary = PathBuf::from("/run/current-system/sw/bin/ssh-keygen");
    let entries = manifest
        .vms
        .iter()
        .filter(|(_, entry)| entry.runtime.capabilities.keys)
        .map(|(vm, entry)| build_key_entry(&bundle, &ssh_keygen_binary, vm, entry))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(d2bd_runtime::wire::keys_list_response(
        public_wire::KeysListResponse { entries },
    ))
}

fn dispatch_keys_show(
    state: &ServerState,
    request: public_wire::KeysShowRequest,
) -> Result<Value, TypedError> {
    let bundle: Bundle = load_json(&state.config.artifacts.bundle_path)?;
    let manifest: ManifestV04 = load_json(&state.config.artifacts.public_manifest_path)?;
    ensure_manifest_entry_runtime_capability(
        manifest.vms.get(&request.vm),
        &request.vm,
        RuntimeCapabilityGate::Keys,
        "keys show",
    )?;
    let ssh_keygen_binary = PathBuf::from("/run/current-system/sw/bin/ssh-keygen");
    let entry = manifest
        .vms
        .get(&request.vm)
        .ok_or_else(|| TypedError::InternalIo {
            context: format!("keys show {}", request.vm),
            detail: "VM not present in public manifest".to_owned(),
        })?;
    let key_entry = build_key_entry(&bundle, &ssh_keygen_binary, &request.vm, entry)?;
    let public_key = read_trimmed_file(
        &bundle.managed_keys.public_key_path(&request.vm),
        &format!("read {} public key", request.vm),
    )?;
    Ok(d2bd_runtime::wire::keys_show_response(
        public_wire::KeysShowResponse {
            vm: key_entry.vm,
            env: key_entry.env,
            managed_key_path: key_entry.managed_key_path,
            public_key,
            fingerprint: key_entry.fingerprint,
            known_hosts_entry: key_entry.known_hosts_entry,
        },
    ))
}

fn build_key_entry(
    bundle: &Bundle,
    ssh_keygen_binary: &Path,
    vm: &str,
    entry: &ManifestVmEntry,
) -> Result<public_wire::KeyEntry, TypedError> {
    let managed_key_path = bundle.managed_keys.effective_key_path(vm);
    let public_key_path = bundle.managed_keys.public_key_path(vm);
    let fingerprint = ssh_keygen::probe_fingerprint(ssh_keygen_binary, &public_key_path)
        .map_err(|err| TypedError::InternalIo {
            context: format!("ssh-keygen -lf {}", public_key_path.display()),
            detail: err.to_string(),
        })?
        .fingerprint;
    Ok(public_wire::KeyEntry {
        vm: vm.to_owned(),
        env: entry.env.clone(),
        managed_key_path: managed_key_path.display().to_string(),
        fingerprint,
        known_hosts_entry: build_known_hosts_entry(entry)?,
    })
}

fn build_known_hosts_entry(entry: &ManifestVmEntry) -> Result<Option<String>, TypedError> {
    let Some(static_ip) = entry.static_ip.as_ref() else {
        return Ok(None);
    };
    let host_public_key = read_trimmed_file(
        &PathBuf::from(&entry.state_dir)
            .join("sshd-host-keys")
            .join("ssh_host_ed25519_key.pub"),
        &format!("read {} host public key", entry.name),
    )?;
    if host_public_key.is_empty() {
        return Ok(None);
    }
    Ok(Some(format!("{static_ip} {host_public_key}")))
}

fn dispatch_broker_usbip_bind(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    request: public_wire::UsbipBindCliRequest,
) -> Result<Value, TypedError> {
    const VERB: &str = "usb attach";
    if let Some(response) = mutating_verb_preflight(VERB, &request.flags, Some(request.vm.as_str()))
    {
        return Ok(response);
    }
    let resolver = load_bundle_resolver(state)?;
    ensure_manifest_entry_runtime_capability(
        resolver.manifest.vms.get(&request.vm),
        &request.vm,
        RuntimeCapabilityGate::UsbHotplug,
        VERB,
    )?;
    if vm_is_qemu_media(&resolver, &request.vm)? {
        return dispatch_broker_qemu_media_attach(state, request, caller_role);
    }
    if let Err(response) = validate_usbip_bus_id_for_daemon(VERB, &request.bus_id) {
        return Ok(response);
    }

    // Fail-closed pre-flight checks for explicit attach:
    //  1. Sysfs presence: reject if the device is not physically present.
    //  2. Active claim exclusivity: reject if another VM already holds this busid.
    // Both checks run before any broker call or firewall mutation.
    check_sysfs_busid_present(&request.bus_id, VERB)?;
    check_usbip_claim_exclusivity(&request.bus_id, &request.vm, VERB)?;

    let Some(manifest_entry) = resolver.find_manifest_vm(&request.vm) else {
        return Ok(daemon_failure_response(
            VERB,
            format!("VM '{}' is not present in the trusted manifest", request.vm),
        ));
    };
    let manifest_entry = serde_json::to_value(manifest_entry).unwrap_or(Value::Null);
    if let Err(response) = ensure_usbip_attach_vm_is_running(
        state,
        &request.vm,
        &request.bus_id,
        VERB,
        &manifest_entry,
        resolver.find_process_vm(&request.vm),
    ) {
        return Ok(response);
    }
    if let Err(summary) = run_guest_usbip_import(
        state,
        &resolver,
        &request.vm,
        &request.bus_id,
        caller_role.clone(),
        d2bd_runtime::guest_control_health::GuestUsbipAction::Detach,
    ) {
        return Ok(daemon_failure_response(VERB, summary));
    }

    // Determine attach path: declared (static bundle intent) vs. explicit.
    let vm_entry = resolver.find_manifest_vm(&request.vm);
    let env = vm_entry.and_then(|e| e.env.as_deref()).unwrap_or("");
    let firewall_id = intent_id_usbip_firewall(env, &request.bus_id);
    let bind_id = intent_id_usbip_bind(env, &request.vm, &request.bus_id);
    let has_declared_intents = resolver.find_usbip_firewall_intent(&firewall_id).is_some()
        && resolver.find_usbip_bind_intent(&bind_id).is_some();

    if has_declared_intents {
        // Declared path: use bundle-ref broker ops (existing behavior).
        let bundle_usbip_bind_intent_ref = BundleOpId::new(bind_id);
        if let Err(response) = dispatch_broker_ack_request_as(
            state,
            VERB,
            "UsbipBind",
            BrokerRequest::UsbipBind(BrokerUsbipBindRequest {
                bundle_usbip_bind_intent_ref,
                tracing_span_id: None,
            }),
            caller_role.clone(),
        ) {
            return Ok(response);
        }
        if let Err(response) = ensure_usbipd_env_ready_for_attach(
            state,
            &resolver,
            &request.vm,
            &request.bus_id,
            VERB,
            None,
        ) {
            compensate_usbip_bind_failure(state, &resolver, &request.vm, &request.bus_id, VERB);
            return Ok(response);
        }
        if let Err(response) = dispatch_broker_ack_request_as(
            state,
            VERB,
            "UsbipProxyReconcile",
            BrokerRequest::UsbipProxyReconcile(BrokerUsbipProxyReconcileRequest {
                scope_id: ScopeId::new(format!("vm:{}", request.vm)),
                tracing_span_id: None,
            }),
            caller_role.clone(),
        ) {
            compensate_usbip_bind_failure(state, &resolver, &request.vm, &request.bus_id, VERB);
            return Ok(response);
        }
    } else {
        // Explicit path: no static bundle intents required.
        let host_uplink_ip = vm_entry
            .and_then(|e| e.usbipd_host_ip.as_deref())
            .unwrap_or("")
            .to_owned();
        let net_uplink_ip = vm_entry
            .and_then(|e| e.static_ip.as_deref())
            .unwrap_or("")
            .to_owned();
        if let Err(response) = dispatch_broker_ack_request_as(
            state,
            VERB,
            "UsbipExplicitFirewallRule",
            BrokerRequest::UsbipExplicitFirewallRule(BrokerUsbipExplicitFirewallRuleRequest {
                bus_id: request.bus_id.clone(),
                env: env.to_owned(),
                host_uplink_ip,
                net_uplink_ip,
                tracing_span_id: None,
            }),
            caller_role.clone(),
        ) {
            return Ok(response);
        }
        if let Err(response) = dispatch_broker_ack_request_as(
            state,
            VERB,
            "UsbipExplicitBind",
            BrokerRequest::UsbipExplicitBind(BrokerUsbipExplicitBindRequest {
                bus_id: request.bus_id.clone(),
                vm: request.vm.clone(),
                env: env.to_owned(),
                tracing_span_id: None,
            }),
            caller_role.clone(),
        ) {
            return Ok(response);
        }
    }

    if let Err(summary) = run_guest_usbip_import(
        state,
        &resolver,
        &request.vm,
        &request.bus_id,
        caller_role,
        d2bd_runtime::guest_control_health::GuestUsbipAction::Attach,
    ) {
        compensate_usbip_bind_failure(state, &resolver, &request.vm, &request.bus_id, VERB);
        return Ok(daemon_failure_response(VERB, summary));
    }
    Ok(applied_response(
        VERB,
        format!(
            "d2b usb attach --apply: bound busid '{}' for vm '{}' and imported it via guestd",
            request.bus_id, request.vm
        ),
    ))
}

fn validate_usbip_bus_id_for_daemon(verb: &str, bus_id: &str) -> Result<(), Value> {
    d2b_contracts::usbip::validate_bus_id(bus_id).map_err(|_| {
        daemon_failure_response(
            verb,
            format!("USBIP busid '{bus_id}' does not match the canonical sysfs bus-id shape"),
        )
    })
}

/// Check whether a validated sysfs busid is currently present in
/// `/sys/bus/usb/devices/<busid>/idVendor`. Returns `Ok(())` if the
/// `idVendor` attribute file is readable (device physically present),
/// or `Err(TypedError::UsbipBusidNotPresent)` if absent (fail-closed gate).
///
/// This is the fail-closed sysfs presence check for explicit attach:
/// reject before any broker call or firewall mutation if the device is absent.
fn check_sysfs_busid_present(busid: &str, verb: &str) -> Result<(), TypedError> {
    let sysfs_path = PathBuf::from(format!("/sys/bus/usb/devices/{busid}/idVendor"));
    let (tx, rx) = mpsc::channel();
    let busid_for_log = busid.to_owned();
    std::thread::Builder::new()
        .name("d2b-usb-sysfs-present".to_owned())
        .spawn(move || {
            let _ = tx.send(std::fs::metadata(sysfs_path).is_ok());
        })
        .map_err(|error| TypedError::InternalIo {
            context: "spawn USB sysfs presence helper".to_owned(),
            detail: error.to_string(),
        })?;
    match rx.recv_timeout(USBIP_SYSFS_PRESENCE_TIMEOUT) {
        Ok(true) => Ok(()),
        Ok(false) => Err(TypedError::UsbipBusidNotPresent {
            busid: busid.to_owned(),
            verb: verb.to_owned(),
        }),
        Err(mpsc::RecvTimeoutError::Timeout) => {
            tracing::warn!(
                busid = %busid_for_log,
                timeout_ms = USBIP_SYSFS_PRESENCE_TIMEOUT.as_millis() as u64,
                "USB sysfs presence check timed out"
            );
            Err(TypedError::UsbipBusidNotPresent {
                busid: busid.to_owned(),
                verb: verb.to_owned(),
            })
        }
        Err(mpsc::RecvTimeoutError::Disconnected) => Err(TypedError::UsbipBusidNotPresent {
            busid: busid.to_owned(),
            verb: verb.to_owned(),
        }),
    }
}

/// Read the current owner of the per-busid OFD lock file under
/// `/run/d2b/locks/usbip/<busid>`.
///
/// Returns `None` if the lock file does not exist or has no content
/// (uncontested). Returns `Some(owner_vm)` if another VM holds the claim.
///
/// The daemon uses this for the active-claim exclusivity check:
/// if the busid is already locked by a different VM, the explicit attach
/// is rejected fail-closed before any broker call.
fn read_usbip_active_claim_owner(busid: &str) -> Option<String> {
    let lock_path = d2b_contracts::usbip::UsbipDaemonClaimRecord::lock_path_for_busid(busid);
    std::fs::read_to_string(&lock_path)
        .ok()
        .map(|content| content.trim().to_owned())
        .filter(|s| !s.is_empty())
}

/// Check that no other VM holds the active claim for a busid.
/// Returns `Ok(())` if the busid is uncontested or already owned by `requesting_vm`.
/// Returns `Err(TypedError::UsbipExplicitClaimConflict)` if another VM holds the claim.
fn check_usbip_claim_exclusivity(
    busid: &str,
    requesting_vm: &str,
    verb: &str,
) -> Result<(), TypedError> {
    match read_usbip_active_claim_owner(busid) {
        Some(owner) if owner != requesting_vm => Err(TypedError::UsbipExplicitClaimConflict {
            busid: busid.to_owned(),
            owner_vm: owner,
            verb: verb.to_owned(),
        }),
        _ => Ok(()),
    }
}

fn usbip_bind_intent_ref_for_daemon(
    resolver: &BundleResolver,
    vm: &str,
    bus_id: &str,
    verb: &str,
) -> Result<BundleOpId, Value> {
    let Some(entry) = resolver.manifest.vms.get(vm) else {
        return Err(daemon_failure_response(
            verb,
            format!("VM '{vm}' is not present in the trusted manifest"),
        ));
    };
    let Some(env) = entry.env.as_deref() else {
        return Err(daemon_failure_response(
            verb,
            format!("VM '{vm}' is not attached to a d2b env"),
        ));
    };
    Ok(BundleOpId::new(intent_id_usbip_bind(env, vm, bus_id)))
}

fn ensure_usbip_attach_vm_is_running(
    state: &ServerState,
    vm: &str,
    bus_id: &str,
    verb: &str,
    manifest_entry: &Value,
    process_vm: Option<&d2b_core::processes::VmProcessDag>,
) -> Result<(), Value> {
    let lifecycle = public_vm_lifecycle(state, vm, manifest_entry, process_vm);
    let lifecycle_state = lifecycle
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("Unknown");
    if lifecycle_state == "Running" {
        return Ok(());
    }

    Err(invalid_request_response_with_summary(
        verb,
        format!(
            "VM '{vm}' is {state}, so USB attach cannot reach guest-control",
            state = lifecycle_state.to_ascii_lowercase()
        ),
        format!(
            "VM '{vm}' is {state}, so USB attach cannot reach guest-control. Start the VM first with `d2b vm start {vm} --apply`, wait until it is running, then retry `d2b usb attach {vm} {bus_id} --apply`.",
            state = lifecycle_state.to_ascii_lowercase()
        ),
    ))
}

fn run_guest_usbip_import(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    bus_id: &str,
    caller_role: BrokerCallerRole,
    action: d2bd_runtime::guest_control_health::GuestUsbipAction,
) -> Result<d2bd_runtime::guest_control_health::GuestUsbipImportResult, String> {
    let Some(entry) = resolver.manifest.vms.get(vm) else {
        return Err(format!("VM '{vm}' is not present in the trusted manifest"));
    };
    let Some(host) = entry.usbipd_host_ip.as_deref() else {
        return Err(format!(
            "VM '{vm}' has no per-env USBIP host IP in the trusted manifest"
        ));
    };
    let params = resolve_guest_control_probe_params(state, resolver, vm).map_err(|detail| {
        tracing::warn!(
            kind = "critical",
            subsystem = "guest-control-usbip",
            error_kind = "transport-io",
            "guest-control USBIP import: probe params unresolved: {detail}"
        );
        format!(
            "guest-control USBIP import for vm '{vm}' could not resolve guest-control transport"
        )
    })?;
    guest_control_bridge::run_usbip_import_on_dedicated_thread(
        params,
        broker_socket_path(state),
        caller_role,
        action,
        host.to_owned(),
        bus_id.to_owned(),
        guest_control_bridge::GUEST_CONTROL_USBIP_IMPORT_TIMEOUT,
    )
    .map_err(|error| guest_usbip_import_error_summary(vm, error))
}

fn run_guest_usbip_status(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    bus_id: &str,
    caller_role: BrokerCallerRole,
    timeout: Duration,
) -> Result<d2bd_runtime::guest_control_health::GuestUsbipStatusResult, GuestUsbipStatusError> {
    let Some(entry) = resolver.manifest.vms.get(vm) else {
        return Err(GuestUsbipStatusError::Failed(format!(
            "VM '{vm}' is not present in the trusted manifest"
        )));
    };
    let Some(host) = entry.usbipd_host_ip.as_deref() else {
        return Err(GuestUsbipStatusError::Failed(format!(
            "VM '{vm}' has no per-env USBIP host IP in the trusted manifest"
        )));
    };
    let params = resolve_guest_control_probe_params(state, resolver, vm).map_err(|detail| {
        tracing::warn!(
            kind = "critical",
            subsystem = "guest-control-usbip",
            error_kind = "transport-io",
            "guest-control USBIP status: probe params unresolved: {detail}"
        );
        GuestUsbipStatusError::Failed(format!(
            "guest-control USBIP status for vm '{vm}' could not resolve guest-control transport"
        ))
    })?;
    guest_control_bridge::run_usbip_status_on_dedicated_thread(
        params,
        broker_socket_path(state),
        caller_role,
        Some(host.to_owned()),
        Some(bus_id.to_owned()),
        timeout,
    )
    .map_err(|error| classify_guest_usbip_status_error(vm, error))
}

fn usbip_lifecycle_claim_for_intent(
    resolver: &BundleResolver,
    vm: &str,
    intent: &d2b_core::bundle_resolver::ResolvedUsbipBindIntent,
) -> Option<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim> {
    let host = resolver
        .manifest
        .vms
        .get(vm)
        .and_then(|entry| entry.usbipd_host_ip.clone())?;
    Some(
        d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim {
            vm: vm.to_owned(),
            env: intent.env.clone(),
            bus_id: intent.bus_id.clone(),
            host,
            claim_ref: intent.intent_id.clone(),
            required: true,
        },
    )
}

fn read_usbip_claim_lock_owner_path(lock_path: &Path) -> io::Result<String> {
    let file = File::open(lock_path)?;
    let mut owner = String::new();
    file.take(128).read_to_string(&mut owner)?;
    Ok(owner.trim().to_owned())
}

fn bounded_usbip_owner_label(owner: &str) -> &str {
    if owner.len() <= 63
        && owner
            .bytes()
            .enumerate()
            .all(|(idx, b)| b.is_ascii_lowercase() || b.is_ascii_digit() || (idx > 0 && b == b'-'))
        && owner.as_bytes().first().is_some_and(u8::is_ascii_lowercase)
    {
        owner
    } else {
        "other"
    }
}

fn same_vm_declared_usbip_start_claims_with_reader(
    resolver: &BundleResolver,
    vm: &str,
    read_owner: impl Fn(&Path) -> io::Result<String>,
) -> Vec<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim> {
    resolver
        .usbip_bind_intent_ids()
        .filter_map(|intent_id| resolver.find_usbip_bind_intent(intent_id))
        .filter(|intent| intent.vm_name == vm)
        .filter_map(|intent| {
            match read_owner(&intent.lock_path) {
                Ok(owner) if owner != vm => {
                    let owner_label = bounded_usbip_owner_label(&owner);
                    tracing::debug!(
                        vm = %vm,
                        bus_id = %intent.bus_id,
                        owner_vm = %owner_label,
                        lock_path = %intent.lock_path.display(),
                        "USBIP start reconciliation observed foreign durable claim; strict broker bind will fail closed if the owner still holds it",
                    );
                }
                Ok(_) => {}
                Err(error) if error.kind() == io::ErrorKind::NotFound => {}
                Err(error) => {
                    tracing::debug!(
                        vm = %vm,
                        bus_id = %intent.bus_id,
                        lock_path = %intent.lock_path.display(),
                        error = %error,
                        "USBIP start reconciliation could not read durable claim; attempting declared broker bind so policy decides",
                    );
                }
            }
            usbip_lifecycle_claim_for_intent(resolver, vm, intent)
        })
        .collect()
}

fn same_vm_declared_usbip_start_claims(
    resolver: &BundleResolver,
    vm: &str,
) -> Vec<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim> {
    same_vm_declared_usbip_start_claims_with_reader(resolver, vm, read_usbip_claim_lock_owner_path)
}

fn same_vm_persisted_usbip_stop_claims_with_reader(
    resolver: &BundleResolver,
    vm: &str,
    read_owner: impl Fn(&Path) -> io::Result<String>,
) -> Vec<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim> {
    resolver
        .usbip_bind_intent_ids()
        .filter_map(|intent_id| resolver.find_usbip_bind_intent(intent_id))
        .filter(|intent| intent.vm_name == vm)
        .filter_map(|intent| {
            let owner = read_owner(&intent.lock_path).ok()?;
            (owner == vm).then(|| usbip_lifecycle_claim_for_intent(resolver, vm, intent))?
        })
        .collect()
}

fn same_vm_persisted_usbip_stop_claims(
    resolver: &BundleResolver,
    vm: &str,
) -> Vec<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim> {
    same_vm_persisted_usbip_stop_claims_with_reader(resolver, vm, read_usbip_claim_lock_owner_path)
}

fn lifecycle_broker_error_kind(
    error: &BrokerErrorResponse,
) -> d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind {
    // Typed match on the wire `kind` slug first so broker errors that
    // have dedicated variants are classified precisely without relying
    // on string matching in the redacted `message` field. The
    // `Broker.LiveHandlerFailed` and similar generic kinds fall through
    // to the legacy substring heuristic as a safety net for any
    // error that still uses the `LiveHandler` variant.
    match error.kind.as_str() {
        "Broker.UsbipDeviceNotAllowed" | "Broker.UsbipPolicyMismatch" => {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::PolicyMismatch
        }
        "Broker.BundleIntentMissing" => {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::MissingBundleIntent
        }
        "Broker.UsbipLockConflict" => {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::LockConflict
        }
        "Broker.UsbipDeviceAbsent" => {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::RuntimeAbsent
        }
        _ => {
            // Fallback: substring match on the combined field for
            // any remaining cases that still use LiveHandler or other
            // generic variants. Policy/intent/lock/absent cases should
            // now be covered by the typed match above, so reaching here
            // is expected only for unexpected or future broker errors.
            let combined =
                format!("{} {} {}", error.kind, error.message, error.action).to_ascii_lowercase();
            if combined.contains("policy")
                || combined.contains("allowlist")
                || combined.contains("topology")
            {
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::PolicyMismatch
            } else if combined.contains("intent") {
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::MissingBundleIntent
            } else if combined.contains("foreign")
                || combined.contains("held")
                || combined.contains("owner")
                || combined.contains("lock")
            {
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::LockConflict
            } else if combined.contains("absent")
                || combined.contains("departed")
                || combined.contains("missing")
                || combined.contains("not present")
            {
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::RuntimeAbsent
            } else {
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::HostReplayFailed
            }
        }
    }
}

fn lifecycle_broker_ack(
    state: &ServerState,
    op_name: &str,
    request: BrokerRequest,
    caller_role: &BrokerCallerRole,
) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
    match dispatch_broker_request_as(state, request, caller_role.clone()) {
        Ok(BrokerResponse::Ack(ack)) if ack.accepted && ack.operation == op_name => Ok(()),
        Ok(BrokerResponse::Error(error)) => Err(
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                lifecycle_broker_error_kind(&error),
                format!("broker {op_name} failed: {}", error.message),
            ),
        ),
        Ok(response) => Err(
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::HostReplayFailed,
                format!(
                    "broker {op_name} returned unexpected response {}",
                    broker_response_kind(&response)
                ),
            ),
        ),
        Err(error) => Err(
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::HostReplayFailed,
                format!("broker {op_name} dispatch failed: {error:?}"),
            ),
        ),
    }
}

struct DaemonUsbipStartReconcileExecutor<'a> {
    state: &'a ServerState,
    resolver: &'a BundleResolver,
    caller_role: BrokerCallerRole,
}

impl d2b_provider_device_usbip::reconcile_state::UsbipVmStartReconcileExecutor
    for DaemonUsbipStartReconcileExecutor<'_>
{
    fn replay_host_bind(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
        let tracing_span_id = tracing_span_id_for_usbip_attempt(attempt);
        lifecycle_broker_ack(
            self.state,
            "UsbipBind",
            BrokerRequest::UsbipBind(BrokerUsbipBindRequest {
                bundle_usbip_bind_intent_ref: BundleOpId::new(claim.claim_ref.clone()),
                tracing_span_id: Some(tracing_span_id),
            }),
            &self.caller_role,
        )
    }

    fn ensure_proxy_ready(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
        let tracing_span_id = tracing_span_id_for_usbip_attempt(attempt);
        ensure_usbipd_env_ready_for_attach(
            self.state,
            self.resolver,
            &claim.vm,
            &claim.bus_id,
            "d2b vm start --apply",
            Some(&tracing_span_id),
        )
        .map_err(|response| {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::ProxyFailed,
                response
                    .get("summary")
                    .and_then(Value::as_str)
                    .unwrap_or("USBIP proxy readiness failed")
                    .to_owned(),
            )
        })?;
        lifecycle_broker_ack(
            self.state,
            "UsbipProxyReconcile",
            BrokerRequest::UsbipProxyReconcile(BrokerUsbipProxyReconcileRequest {
                scope_id: ScopeId::new(format!("vm:{}", claim.vm)),
                tracing_span_id: Some(tracing_span_id),
            }),
            &self.caller_role,
        )
        .map_err(|mut error| {
            error.kind =
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::ProxyFailed;
            error
        })
    }

    fn guest_status(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        _attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<
        d2b_provider_device_usbip::reconcile_state::UsbipGuestImportState,
        d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError,
    > {
        let status = run_guest_usbip_status(
            self.state,
            self.resolver,
            &claim.vm,
            &claim.bus_id,
            self.caller_role.clone(),
            guest_control_bridge::GUEST_CONTROL_USBIP_IMPORT_TIMEOUT,
        )
        .map_err(|error| {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::GuestFailed,
                error.summary().to_owned(),
            )
        })?;
        let imported = status
            .imports
            .iter()
            .any(|entry| entry.host == claim.host && entry.bus_id == claim.bus_id);
        Ok(if imported {
            d2b_provider_device_usbip::reconcile_state::UsbipGuestImportState::Imported
        } else {
            d2b_provider_device_usbip::reconcile_state::UsbipGuestImportState::Detached
        })
    }

    fn guest_import(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        _attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
        run_guest_usbip_import(
            self.state,
            self.resolver,
            &claim.vm,
            &claim.bus_id,
            self.caller_role.clone(),
            d2bd_runtime::guest_control_health::GuestUsbipAction::Attach,
        )
        .map(|_| ())
        .map_err(|summary| {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::GuestFailed,
                summary,
            )
        })
    }
}

struct DaemonUsbipStopCleanupExecutor<'a> {
    state: &'a ServerState,
    caller_role: BrokerCallerRole,
}

impl d2b_provider_device_usbip::reconcile_state::UsbipVmStopCarrierCleanup
    for DaemonUsbipStopCleanupExecutor<'_>
{
    fn detach_guest_import(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        _attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
        let resolver = load_bundle_resolver(self.state).map_err(|error| {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::GuestFailed,
                format!("{error:?}"),
            )
        })?;
        run_guest_usbip_import(
            self.state,
            &resolver,
            &claim.vm,
            &claim.bus_id,
            self.caller_role.clone(),
            d2bd_runtime::guest_control_health::GuestUsbipAction::Detach,
        )
        .map(|_| ())
        .map_err(|summary| {
            d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError::new(
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::GuestFailed,
                summary,
            )
        })
    }

    fn cleanup_host_carrier_preserve_claim(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
        let tracing_span_id = tracing_span_id_for_usbip_attempt(attempt);
        lifecycle_broker_ack(
            self.state,
            "UsbipUnbind",
            BrokerRequest::UsbipUnbind(BrokerUsbipUnbindRequest {
                bundle_usbip_bind_intent_ref: BundleOpId::new(claim.claim_ref.clone()),
                preserve_durable_claim: true,
                tracing_span_id: Some(tracing_span_id),
            }),
            &self.caller_role,
        )
    }

    fn reconcile_proxy(
        &mut self,
        claim: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleClaim,
        attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
    ) -> Result<(), d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStepError> {
        let tracing_span_id = tracing_span_id_for_usbip_attempt(attempt);
        lifecycle_broker_ack(
            self.state,
            "UsbipProxyReconcile",
            BrokerRequest::UsbipProxyReconcile(BrokerUsbipProxyReconcileRequest {
                scope_id: ScopeId::new(format!("vm:{}", claim.vm)),
                tracing_span_id: Some(tracing_span_id),
            }),
            &self.caller_role,
        )
        .map_err(|mut error| {
            error.kind =
                d2b_provider_device_usbip::reconcile_state::UsbipLifecycleFailureKind::ProxyFailed;
            error
        })
    }
}

fn emit_usbip_lifecycle_observations(
    phase: &str,
    report: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleReconcileReport,
) {
    for claim in &report.claims {
        for reason in &claim.degraded {
            tracing::warn!(
                kind = "critical",
                subsystem = "usbip-lifecycle",
                phase = phase,
                vm = %claim.vm,
                env = %claim.env,
                bus_id = %claim.bus_id,
                reason = ?reason.code,
                remediation = %reason.remediation,
                fatal = claim.fatal,
                "USBIP lifecycle reconciliation degraded"
            );
        }
    }
}

fn usbip_lifecycle_report_summary(
    phase: &str,
    report: &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleReconcileReport,
) -> Option<String> {
    if report.claims.is_empty() {
        return None;
    }
    let claims = report.claims.len();
    let degraded = report.degraded_count();
    let imported = report
        .claims
        .iter()
        .filter(|claim| {
            claim.completed.contains(
                &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStep::GuestImport,
            )
        })
        .count();
    let preserved = report
        .claims
        .iter()
        .filter(|claim| {
            claim.completed.contains(
                &d2b_provider_device_usbip::reconcile_state::UsbipLifecycleStep::PreserveDurableClaim,
            )
        })
        .count();
    let mut summary = match phase {
        "start" => format!(
            "USBIP reconciliation inspected {claims} persisted claim(s), imported {imported}, degraded {degraded}"
        ),
        "stop" => format!(
            "USBIP cleanup inspected {claims} host-session claim(s), preserved {preserved}, degraded {degraded}"
        ),
        _ => format!("USBIP lifecycle inspected {claims} persisted claim(s), degraded {degraded}"),
    };
    if let Some(reason) = report.first_fatal_reason() {
        summary.push_str(&format!("; fatal: {}", reason.summary));
    } else if degraded > 0 && phase == "start" {
        summary.push_str("; VM boot continues where policy permits; inspect `d2b usb status` before using affected devices");
    } else if degraded > 0 {
        summary.push_str(
            "; VM stop continues; inspect `d2b usb status` before restarting affected devices",
        );
    }
    Some(summary)
}

fn new_usbip_reconcile_attempt(
    phase: &str,
) -> d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext {
    let phase = match phase {
        "start" | "stop" => phase,
        _ => "other",
    };
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    let bounded = format!("usb-{phase}-{nanos:016x}");
    let correlation_id =
        d2b_provider_device_usbip::reconcile_state::UsbipReconcileCorrelationId::new(&bounded)
            .or_else(|| {
                d2b_provider_device_usbip::reconcile_state::UsbipReconcileCorrelationId::new(
                    format!("usb-{phase}"),
                )
            })
            .expect("static USBIP reconcile correlation id is valid");
    d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext { correlation_id }
}

fn tracing_span_id_for_usbip_attempt(
    attempt: &d2b_provider_device_usbip::reconcile_state::UsbipReconcileAttemptContext,
) -> TracingSpanId {
    TracingSpanId::new(attempt.correlation_id.as_str().to_owned())
}

fn reconcile_usbip_after_vm_start(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    caller_role: BrokerCallerRole,
) -> Option<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleReconcileReport> {
    let claims = same_vm_declared_usbip_start_claims(resolver, vm);
    if claims.is_empty() {
        return None;
    }
    let attempt = new_usbip_reconcile_attempt("start");
    let mut executor = DaemonUsbipStartReconcileExecutor {
        state,
        resolver,
        caller_role,
    };
    let report = d2b_provider_device_usbip::reconcile_state::reconcile_usbip_vm_start_claims(
        &claims,
        &attempt,
        &mut executor,
    );
    emit_usbip_lifecycle_observations("start", &report);
    Some(report)
}

const USBIP_STRICT_RECONCILE_TIMEOUT: Duration = Duration::from_secs(15);
const USBIP_STRICT_RECONCILE_BACKOFF: Duration = Duration::from_secs(2);

fn reconcile_usbip_after_vm_start_until_converged(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    caller_role: BrokerCallerRole,
    timeout: Duration,
    backoff: Duration,
) -> Option<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleReconcileReport> {
    let deadline = Instant::now() + timeout;
    loop {
        let report = reconcile_usbip_after_vm_start(state, resolver, vm, caller_role.clone())?;
        if report.degraded_count() == 0 || report.fatal() || Instant::now() >= deadline {
            return Some(report);
        }
        thread::sleep(backoff);
    }
}

fn usbip_start_reconciles_synchronously(request: &public_wire::VmLifecycleRequest) -> bool {
    !request.no_wait_api
}

const USBIP_BACKGROUND_RECONCILE_TIMEOUT: Duration = Duration::from_secs(120);
const USBIP_BACKGROUND_RECONCILE_BACKOFF: Duration = Duration::from_secs(5);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UsbipBackgroundReconcileSpawn {
    NoClaims,
    AlreadyRunning,
    Spawned,
}

struct UsbipBackgroundReconcileGuard {
    coordinator: Arc<Mutex<ZoneCoordinator>>,
    zone: ZoneId,
}

impl UsbipBackgroundReconcileGuard {
    fn try_acquire(state: &ServerState, vm: &str) -> Option<Self> {
        let zone =
            d2bd_runtime::zone_authority::authoritative_zone_for_vm(&state.zone_coordinator, vm)
                .ok()?;
        let coordinator = Arc::clone(&state.zone_coordinator);
        coordinator.lock().ok()?.begin_usbip_reconcile(&zone).ok()?;
        Some(Self { coordinator, zone })
    }
}

impl Drop for UsbipBackgroundReconcileGuard {
    fn drop(&mut self) {
        if let Ok(mut coordinator) = self.coordinator.lock() {
            let _ = coordinator.finish_usbip_reconcile(&self.zone);
        }
    }
}

fn spawn_usbip_reconcile_after_vm_start(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    runner_role_id: &str,
    caller_role: BrokerCallerRole,
) -> UsbipBackgroundReconcileSpawn {
    if same_vm_declared_usbip_start_claims(resolver, vm).is_empty() {
        return UsbipBackgroundReconcileSpawn::NoClaims;
    }
    let Some(guard) = UsbipBackgroundReconcileGuard::try_acquire(state, vm) else {
        return UsbipBackgroundReconcileSpawn::AlreadyRunning;
    };

    let state = state.clone();
    let resolver = resolver.clone();
    let vm = vm.to_owned();
    let log_vm = vm.clone();
    let runner_role_id = runner_role_id.to_owned();
    let thread_name = format!("d2b-usbip-start-{vm}");
    if let Err(error) = thread::Builder::new().name(thread_name).spawn(move || {
        let _guard = guard;
        let deadline = Instant::now() + USBIP_BACKGROUND_RECONCILE_TIMEOUT;
        loop {
            if !state.pidfd_table.contains(&vm, &runner_role_id) {
                tracing::warn!(
                    vm = %vm,
                    runner_role_id = %runner_role_id,
                    "USBIP background start reconciliation aborted because VM runner is no longer supervised",
                );
                return;
            }

            let Some(report) =
                reconcile_usbip_after_vm_start(&state, &resolver, &vm, caller_role.clone())
            else {
                return;
            };
            let degraded = report.degraded_count();
            if degraded == 0 {
                tracing::info!(
                    vm = %vm,
                    claims = report.claims.len(),
                    "USBIP background start reconciliation converged",
                );
                return;
            }
            if report.fatal() {
                let reason = report
                    .first_fatal_reason()
                    .map(|reason| reason.code.telemetry_label())
                    .unwrap_or("unknown");
                tracing::warn!(
                    vm = %vm,
                    claims = report.claims.len(),
                    degraded,
                    reason,
                    "USBIP background start reconciliation failed closed",
                );
                return;
            }
            if Instant::now() >= deadline {
                tracing::warn!(
                    vm = %vm,
                    claims = report.claims.len(),
                    degraded,
                    "USBIP background start reconciliation timed out; retry `d2b usb attach` or a strict VM start",
                );
                return;
            }
            thread::sleep(USBIP_BACKGROUND_RECONCILE_BACKOFF);
        }
    }) {
        tracing::warn!(
            vm = %log_vm,
            error = %error,
            "failed to spawn USBIP background start reconciliation worker",
        );
        return UsbipBackgroundReconcileSpawn::NoClaims;
    }
    UsbipBackgroundReconcileSpawn::Spawned
}

fn cleanup_usbip_before_vm_stop(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    caller_role: BrokerCallerRole,
) -> Option<d2b_provider_device_usbip::reconcile_state::UsbipLifecycleReconcileReport> {
    let claims = same_vm_persisted_usbip_stop_claims(resolver, vm);
    if claims.is_empty() {
        return None;
    }
    let attempt = new_usbip_reconcile_attempt("stop");
    let mut executor = DaemonUsbipStopCleanupExecutor { state, caller_role };
    let report = d2b_provider_device_usbip::reconcile_state::cleanup_usbip_vm_stop_claims(
        &claims,
        &attempt,
        &mut executor,
    );
    emit_usbip_lifecycle_observations("stop", &report);
    Some(report)
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum UsbipClaimLockProbe {
    None,
    Present,
    Unknown(String),
}

fn probe_usbip_claim_locks_for_vm_without_bundle(
    state: &ServerState,
    vm: &str,
) -> UsbipClaimLockProbe {
    let usbip_locks_dir = state.config.locks_dir.join("usbip");
    let entries = match fs::read_dir(&usbip_locks_dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return UsbipClaimLockProbe::None,
        Err(error) => {
            return UsbipClaimLockProbe::Unknown(format!(
                "could not inspect USBIP lock directory {}: {error}",
                usbip_locks_dir.display()
            ));
        }
    };

    for entry in entries {
        let entry = match entry {
            Ok(entry) => entry,
            Err(error) => {
                return UsbipClaimLockProbe::Unknown(format!(
                    "could not inspect USBIP lock directory {}: {error}",
                    usbip_locks_dir.display()
                ));
            }
        };
        let owner = match fs::read_to_string(entry.path()) {
            Ok(owner) => owner,
            Err(error) if error.kind() == io::ErrorKind::NotFound => continue,
            Err(error) => {
                return UsbipClaimLockProbe::Unknown(format!(
                    "could not inspect USBIP claim lock {}: {error}",
                    entry.path().display()
                ));
            }
        };
        if owner.trim() == vm {
            return UsbipClaimLockProbe::Present;
        }
    }

    UsbipClaimLockProbe::None
}

fn guest_usbip_import_error_summary(
    vm: &str,
    error: d2bd_runtime::guest_control_health::GuestUsbipImportError,
) -> String {
    use d2bd_runtime::guest_control_health::{
        GuestControlHealthError as H, GuestUsbipImportError as E,
    };
    let detail = match error {
        E::Probe(H::TransportIo) | E::Probe(H::Signer) | E::Probe(H::Ttrpc) => {
            "guest-control transport unavailable"
        }
        E::Probe(H::Timeout) => "guest-control USBIP import timed out",
        E::Probe(H::AuthFailed) | E::Probe(H::StaleSession) => {
            "guest-control authentication failed"
        }
        E::Probe(H::Protocol) | E::Protocol => "guest-control USBIP protocol error",
        E::CapabilityUnavailable => "guest does not advertise USBIP import capability",
        E::UsbipUnavailable => "guestd has no usable usbip binary",
        E::InvalidBusId => "guestd rejected the USBIP busid",
        E::InvalidHost => "guestd rejected the USBIP backend host",
        E::CommandFailed => "guest usbip command failed",
        E::CommandTimeout => "guest usbip command timed out",
        E::InvalidOutput => "guest usbip command output was invalid",
    };
    format!("guest-control USBIP import failed for vm '{vm}': {detail}")
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum GuestUsbipStatusError {
    Timeout(String),
    Failed(String),
}

impl GuestUsbipStatusError {
    fn summary(&self) -> &str {
        match self {
            Self::Timeout(summary) | Self::Failed(summary) => summary,
        }
    }
}

fn classify_guest_usbip_status_error(
    vm: &str,
    error: d2bd_runtime::guest_control_health::GuestUsbipImportError,
) -> GuestUsbipStatusError {
    let is_timeout = matches!(
        error,
        d2bd_runtime::guest_control_health::GuestUsbipImportError::Probe(
            d2bd_runtime::guest_control_health::GuestControlHealthError::Timeout
        ) | d2bd_runtime::guest_control_health::GuestUsbipImportError::CommandTimeout
    );
    let summary = guest_usbip_import_error_summary(vm, error);
    if is_timeout {
        GuestUsbipStatusError::Timeout(summary)
    } else {
        GuestUsbipStatusError::Failed(summary)
    }
}

fn compensate_usbip_bind_failure(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    bus_id: &str,
    verb: &str,
) {
    let intent_ref = match usbip_bind_intent_ref_for_daemon(resolver, vm, bus_id, verb) {
        Ok(intent_ref) => intent_ref,
        Err(response) => {
            tracing::warn!(vm = %vm, bus_id = %bus_id, response = %response, "USBIP attach compensation could not resolve bind intent");
            return;
        }
    };
    if let Err(response) = dispatch_broker_ack_request(
        state,
        verb,
        "UsbipUnbind",
        BrokerRequest::UsbipUnbind(BrokerUsbipUnbindRequest {
            bundle_usbip_bind_intent_ref: intent_ref,
            preserve_durable_claim: false,
            tracing_span_id: None,
        }),
    ) {
        tracing::warn!(vm = %vm, bus_id = %bus_id, response = %response, "USBIP attach compensation unbind failed");
    }
    if let Err(response) = dispatch_broker_ack_request(
        state,
        verb,
        "UsbipProxyReconcile",
        BrokerRequest::UsbipProxyReconcile(BrokerUsbipProxyReconcileRequest {
            scope_id: ScopeId::new(format!("vm:{vm}")),
            tracing_span_id: None,
        }),
    ) {
        tracing::warn!(vm = %vm, bus_id = %bus_id, response = %response, "USBIP attach compensation proxy reconcile failed");
    }
}

fn ensure_usbipd_env_ready_for_attach(
    state: &ServerState,
    resolver: &BundleResolver,
    vm: &str,
    bus_id: &str,
    verb: &str,
    tracing_span_id: Option<&TracingSpanId>,
) -> Result<(), Value> {
    let Some(entry) = resolver.manifest.vms.get(vm) else {
        return Err(daemon_failure_response(
            verb,
            format!("VM '{vm}' is not present in the trusted manifest"),
        ));
    };
    let Some(env) = entry.env.as_deref() else {
        return Err(daemon_failure_response(
            verb,
            format!("VM '{vm}' is not attached to a d2b env"),
        ));
    };
    let Some(host_ip) = entry.usbipd_host_ip.as_deref() else {
        return Err(daemon_failure_response(
            verb,
            format!("VM '{vm}' has no per-env USBIP host IP in the trusted manifest"),
        ));
    };

    let specs: Vec<_> = d2bd_runtime::usbipd_perenv_autostart::derive_per_env_usbipd_specs(
        &resolver.manifest,
        &resolver.host,
    )
    .into_iter()
    .filter(|spec| spec.env == env)
    .collect();
    if specs.len() != 2 {
        return Err(daemon_failure_response(
            verb,
            format!("trusted bundle has no complete per-env USBIP runner plan for env '{env}'"),
        ));
    }

    // Core context must be valid before firewall or runner effects.
    let _production_context = usbip_production::UsbipBindingContext::before_host_effects(
        vm,
        env,
        intent_id_usbip_bind(env, vm, bus_id),
        intent_id_runner(vm, "usbip"),
        format!("{env}:{bus_id}").as_bytes(),
    )
    .map_err(|error| daemon_failure_response(verb, error.to_string()))?;

    dispatch_broker_ack_request(
        state,
        verb,
        "UsbipBindFirewallRule",
        BrokerRequest::UsbipBindFirewallRule(BrokerUsbipBindFirewallRuleRequest {
            bundle_usbip_firewall_intent_ref: BundleOpId::new(intent_id_usbip_firewall(
                env, bus_id,
            )),
            tracing_span_id: tracing_span_id.cloned(),
        }),
    )?;

    let spawner = BrokerPerEnvUsbipdSpawner {
        state: Arc::new(state.clone()),
        tracing_span_id: tracing_span_id.cloned(),
    };
    let report =
        d2bd_runtime::usbipd_perenv_autostart::execute_usbipd_perenv_autostart(&specs, &spawner);
    let failed: Vec<String> = report
        .specs
        .iter()
        .filter_map(|entry| match &entry.outcome {
            d2bd_runtime::usbipd_perenv_autostart::PerEnvUsbipdOutcome::Failed { reason } => {
                Some(format!("{}:{reason}", entry.role.role_id()))
            }
            d2bd_runtime::usbipd_perenv_autostart::PerEnvUsbipdOutcome::SkippedPendingBundle => {
                Some(format!("{}:bundle-intent-missing", entry.role.role_id()))
            }
            d2bd_runtime::usbipd_perenv_autostart::PerEnvUsbipdOutcome::Spawned
            | d2bd_runtime::usbipd_perenv_autostart::PerEnvUsbipdOutcome::AlreadyRunning => None,
        })
        .collect();
    if !failed.is_empty() {
        return Err(daemon_failure_response(
            verb,
            format!(
                "per-env USBIP runners for env '{env}' did not start cleanly: {}",
                failed.join(", ")
            ),
        ));
    }

    let backend_port = specs[0].backend_port;
    wait_for_tcp_port("127.0.0.1", backend_port, Duration::from_secs(10))
        .and_then(|_| wait_for_tcp_port(host_ip, 3240, Duration::from_secs(10)))
        .map_err(|reason| {
            daemon_failure_response(
                verb,
                format!("per-env USBIP runners for env '{env}' did not become ready: {reason}"),
            )
        })
}

fn dispatch_broker_usbip_unbind(
    state: &ServerState,
    caller_role: BrokerCallerRole,
    request: public_wire::UsbipUnbindCliRequest,
) -> Result<Value, TypedError> {
    const VERB: &str = "usb detach";
    if let Some(response) = mutating_verb_preflight(VERB, &request.flags, Some(request.vm.as_str()))
    {
        return Ok(response);
    }
    let resolver = load_bundle_resolver(state)?;
    ensure_manifest_entry_runtime_capability(
        resolver.manifest.vms.get(&request.vm),
        &request.vm,
        RuntimeCapabilityGate::UsbHotplug,
        VERB,
    )?;
    if vm_is_qemu_media(&resolver, &request.vm)? {
        return dispatch_broker_qemu_media_detach(state, request, caller_role);
    }
    if let Err(response) = validate_usbip_bus_id_for_daemon(VERB, &request.bus_id) {
        return Ok(response);
    }
    let intent_ref =
        match usbip_bind_intent_ref_for_daemon(&resolver, &request.vm, &request.bus_id, VERB) {
            Ok(intent_ref) => intent_ref,
            Err(response) => return Ok(response),
        };

    if let Err(summary) = run_guest_usbip_import(
        state,
        &resolver,
        &request.vm,
        &request.bus_id,
        caller_role.clone(),
        d2bd_runtime::guest_control_health::GuestUsbipAction::Detach,
    ) {
        tracing::warn!(
            vm = %request.vm,
            bus_id = %request.bus_id,
            summary = %summary,
            "USBIP guest detach failed; continuing host-side detach cleanup"
        );
    }

    if let Err(response) = dispatch_broker_ack_request_as(
        state,
        VERB,
        "UsbipUnbind",
        BrokerRequest::UsbipUnbind(BrokerUsbipUnbindRequest {
            bundle_usbip_bind_intent_ref: intent_ref,
            preserve_durable_claim: false,
            tracing_span_id: None,
        }),
        caller_role.clone(),
    ) {
        return Ok(response);
    }

    if let Err(response) = dispatch_broker_ack_request_as(
        state,
        VERB,
        "UsbipProxyReconcile",
        BrokerRequest::UsbipProxyReconcile(BrokerUsbipProxyReconcileRequest {
            scope_id: ScopeId::new(format!("vm:{}", request.vm)),
            tracing_span_id: None,
        }),
        caller_role.clone(),
    ) {
        return Ok(response);
    }

    Ok(applied_response(
        VERB,
        format!(
            "d2b usb detach --apply: detached busid '{}' from vm '{}' and released the host claim",
            request.bus_id, request.vm
        ),
    ))
}

fn vm_is_qemu_media(resolver: &BundleResolver, vm: &str) -> Result<bool, TypedError> {
    let Some(entry) = resolver.find_manifest_vm(vm) else {
        return Ok(false);
    };
    Ok(!vm_requires_nixos_state_preflights(entry))
}

fn vm_requires_nixos_state_preflights(entry: &ManifestVmEntry) -> bool {
    entry.runtime.kind != d2b_core::runtime::RuntimeKind::QemuMedia
}

fn refresh_qemu_media_registry_index_if_needed(
    state: &ServerState,
    resolver: &BundleResolver,
) -> Result<(), TypedError> {
    refresh_qemu_media_registry_index_if_needed_as(
        state,
        resolver,
        BrokerCallerRole::AdminUid {
            uid: state.daemon_uid,
        },
    )
}

fn refresh_qemu_media_registry_index_if_needed_as(
    state: &ServerState,
    resolver: &BundleResolver,
    caller_role: BrokerCallerRole,
) -> Result<(), TypedError> {
    if resolver.host.qemu_media.is_none() {
        return Ok(());
    }
    match dispatch_broker_request_as(
        state,
        BrokerRequest::QemuMediaRefreshRegistry(BrokerQemuMediaRefreshRegistryRequest {
            tracing_span_id: None,
        }),
        caller_role,
    )? {
        BrokerResponse::QemuMediaRefreshRegistry(_) => Ok(()),
        BrokerResponse::Error(error) => Err(TypedError::InternalIo {
            context: "refresh qemu-media registry index".to_owned(),
            detail: format!("{}:{}", error.operation, error.kind),
        }),
        other => Err(TypedError::InternalIo {
            context: "refresh qemu-media registry index".to_owned(),
            detail: format!(
                "unexpected broker response {}",
                broker_response_kind(&other)
            ),
        }),
    }
}

fn dispatch_broker_qemu_media_attach(
    state: &ServerState,
    request: public_wire::UsbipBindCliRequest,
    caller_role: BrokerCallerRole,
) -> Result<Value, TypedError> {
    const VERB: &str = "usb attach";
    if let Err(err) = d2b_host::media::validate_usb_busid(&request.bus_id) {
        return Ok(invalid_request_response(
            VERB,
            format!("invalid USB busid selector: {err}"),
        ));
    }
    match dispatch_broker_request_as(
        state,
        BrokerRequest::QemuMediaAttach(BrokerQemuMediaHotplugRequest {
            vm_id: VmId::new(request.vm.clone()),
            bus_id: request.bus_id,
            tracing_span_id: None,
        }),
        caller_role,
    ) {
        Ok(BrokerResponse::QemuMediaAttach(response)) => Ok(applied_response(
            VERB,
            qemu_media_hotplug_summary(VERB, "attached", &response),
        )),
        Ok(BrokerResponse::Error(error)) => broker_error_for_qemu_media_hotplug(VERB, error),
        Ok(other) => {
            tracing::warn!(
                broker_response_kind = %broker_response_kind(&other),
                "broker returned unexpected qemu-media attach response"
            );
            let (summary, remediation) =
                redact_broker_error_for_launcher("QemuMediaAttach", None, "Broker.Protocol");
            Ok(broker_failure_response(VERB, summary, remediation, None))
        }
        Err(error) => {
            tracing::warn!(error = ?error, "qemu-media attach broker dispatch failed");
            let (summary, remediation) =
                redact_broker_dispatch_failure_for_launcher("QemuMediaAttach");
            Ok(broker_failure_response(VERB, summary, remediation, None))
        }
    }
}

