fn shell_resource_get(
    client: &DaemonResourceApiClient,
    zone: &ZoneId,
    name: &public_wire::ShellName,
) -> Result<Option<d2b_contracts_resource::v3::ResourceEnvelope>, TypedError> {
    let resource_ref = ResourceRef::parse(&format!(
        "shell-terminal.d2bus.org.ShellSession/{}",
        name.as_str()
    ))
    .map_err(|_| shell_protocol_failed())?;
    let mut request = resource_wire::GetRequest::new();
    request.meta = protobuf::MessageField::some(DaemonShellAuthority::shell_resource_request_meta(
        "shell-session-get",
    ));
    request.target = protobuf::MessageField::some(DaemonShellAuthority::shell_resource_identity(
        zone,
        &resource_ref,
    ));
    let mut projection = resource_wire::Projection::new();
    projection.kind =
        protobuf::EnumOrUnknown::new(resource_wire::ProjectionKind::PROJECTION_KIND_FULL);
    request.projection = protobuf::MessageField::some(projection);
    let response = block_on_future(client.get(request));
    let Some(resource) = response.resource.as_ref() else {
        return match response
            .error
            .as_ref()
            .and_then(|error| error.kind.enum_value().ok())
        {
            Some(resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_NOT_FOUND) => {
                Ok(None)
            }
            Some(_) | None => Err(response
                .error
                .as_ref()
                .map(shell_resource_api_error)
                .unwrap_or_else(shell_protocol_failed)),
        };
    };
    d2b_contracts_resource::v3::ResourceEnvelope::from_json(&resource.canonical_json)
        .map(Some)
        .map_err(|_| shell_protocol_failed())
}

fn shell_resource_api_error(error: &resource_wire::ResourceError) -> TypedError {
    match error.kind.enum_value().ok() {
        Some(resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_AUTHORIZATION_DENIED) => {
            TypedError::AuthzNotAdmin {
                verb: "shell".to_owned(),
            }
        }
        Some(resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_TIMEOUT) => {
            shell_failed(d2bd_runtime::typed_error::GuestControlShellErrorKind::Timeout)
        }
        Some(
            resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_PROVIDER_UNAVAILABLE
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_PLANE_UNAVAILABLE,
        ) => shell_transport_failed(),
        Some(resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_BACKPRESSURE) => {
            shell_failed(d2bd_runtime::typed_error::GuestControlShellErrorKind::Capacity)
        }
        Some(
            resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_NOT_FOUND
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_ALREADY_EXISTS
            | resource_wire::ResourceErrorKind::RESOURCE_ERROR_KIND_RESOURCE_CONFLICT,
        ) => shell_failed(d2bd_runtime::typed_error::GuestControlShellErrorKind::NotFound),
        _ => shell_protocol_failed(),
    }
}

fn map_shell_authority_error(error: ShellTerminalError) -> TypedError {
    match error {
        ShellTerminalError::CapacityExceeded => {
            shell_failed(d2bd_runtime::typed_error::GuestControlShellErrorKind::Capacity)
        }
        ShellTerminalError::StaleSessionGeneration
        | ShellTerminalError::CapabilityReused
        | ShellTerminalError::CapabilitySessionMismatch
        | ShellTerminalError::AttachmentUnknown => {
            shell_failed(d2bd_runtime::typed_error::GuestControlShellErrorKind::StaleSession)
        }
        ShellTerminalError::NotAuthorized => TypedError::AuthzNotAdmin {
            verb: "shell".to_owned(),
        },
        ShellTerminalError::WrongZone
        | ShellTerminalError::InvalidName
        | ShellTerminalError::CapacityOutOfRange
        | ShellTerminalError::InvalidLoginShell
        | ShellTerminalError::RelayHostUserDomainDenied
        | ShellTerminalError::WorkloadIdentityMismatch
        | ShellTerminalError::GuestUserDomainUnsupported
        | ShellTerminalError::SupervisorAmbiguous => shell_protocol_failed(),
    }
}

fn shell_session_entry(
    bytes: &[u8],
    default_name: &public_wire::ShellName,
) -> Result<public_wire::ShellListEntry, TypedError> {
    let value: Value = serde_json::from_slice(bytes).map_err(|_| shell_protocol_failed())?;
    let name = value
        .pointer("/metadata/name")
        .and_then(Value::as_str)
        .and_then(|name| public_wire::ShellName::new(name).ok())
        .ok_or_else(shell_protocol_failed)?;
    let attached = value
        .pointer("/status/resource/attached")
        .and_then(Value::as_bool)
        .or_else(|| value.pointer("/status/attached").and_then(Value::as_bool))
        .unwrap_or(false);
    let state = match value.pointer("/status/phase").and_then(Value::as_str) {
        Some("Failed") | Some("Degraded") => public_wire::ShellSessionState::FeatureDisabled,
        Some("Deleted") => public_wire::ShellSessionState::Killed,
        _ if attached => public_wire::ShellSessionState::Attached,
        _ => public_wire::ShellSessionState::Detached,
    };
    Ok(public_wire::ShellListEntry {
        is_default: name == *default_name,
        name,
        state,
        attached,
    })
}

fn production_guest_shell_list(
    state: &ServerState,
    vm: &str,
) -> Result<public_wire::ShellListResult, TypedError> {
    let _driver = require_guest_component_session(state, vm)?;
    let (zone, client) = shell_resource_client(state)?;
    let target = ResourceRef::parse(&format!("Guest/{vm}")).map_err(|_| shell_protocol_failed())?;
    let default_name = public_wire::ShellName::new("primary").expect("valid default shell name");
    let mut request = resource_wire::ListRequest::new();
    request.meta = protobuf::MessageField::some(DaemonShellAuthority::shell_resource_request_meta(
        "shell-session-list",
    ));
    request
        .resource_types
        .push("shell-terminal.d2bus.org.ShellSession".to_owned());
    let mut filter = resource_wire::ListFilter::new();
    filter.field = "spec.executionRef".to_owned();
    filter.values.push(target.to_canonical_string());
    request.filters.push(filter);
    request.page_size = 256;
    let mut projection = resource_wire::Projection::new();
    projection.kind =
        protobuf::EnumOrUnknown::new(resource_wire::ProjectionKind::PROJECTION_KIND_FULL);
    request.projection = protobuf::MessageField::some(projection);
    let response = block_on_future(client.list(request));
    if let Some(error) = response.error.as_ref() {
        return Err(shell_resource_api_error(error));
    }
    let sessions = response
        .resources
        .iter()
        .map(|resource| shell_session_entry(&resource.canonical_json, &default_name))
        .collect::<Result<Vec<_>, _>>()?;
    let _ = zone;
    Ok(public_wire::ShellListResult {
        default_name,
        sessions,
    })
}

fn production_guest_shell_detach(
    state: &ServerState,
    vm: &str,
    name: Option<public_wire::ShellName>,
) -> Result<public_wire::ShellDetachResult, TypedError> {
    let _driver = require_guest_component_session(state, vm)?;
    let (zone, client) = shell_resource_client(state)?;
    let name = name.unwrap_or_else(|| public_wire::ShellName::new("primary").expect("default"));
    let Some(envelope) = shell_resource_get(&client, &zone, &name)? else {
        return Err(TypedError::WorkloadTargetNotFound {
            target: format!("shell-terminal.d2bus.org.ShellSession/{}", name.as_str()),
        });
    };
    let _ = envelope;
    Ok(public_wire::ShellDetachResult {
        resolved_name: name,
        detached: true,
        cause: Some(public_wire::ShellCloseCause::ClientDetach),
    })
}

fn production_guest_shell_kill(
    state: &ServerState,
    vm: &str,
    name: public_wire::ShellName,
) -> Result<public_wire::ShellKillResult, TypedError> {
    let _driver = require_guest_component_session(state, vm)?;
    let (zone, client) = shell_resource_client(state)?;
    let Some(envelope) = shell_resource_get(&client, &zone, &name)? else {
        return Err(TypedError::WorkloadTargetNotFound {
            target: format!("shell-terminal.d2bus.org.ShellSession/{}", name.as_str()),
        });
    };
    let session = shell_session_from_resource(&envelope)?;
    daemon_shell_authority(state)
        .remove_supervisor_process_resource(&session)
        .map_err(map_shell_authority_error)?;
    let resource_ref = ResourceRef::parse(&format!(
        "shell-terminal.d2bus.org.ShellSession/{}",
        name.as_str()
    ))
    .map_err(|_| shell_protocol_failed())?;
    let mut mutation = resource_wire::Mutation::new();
    mutation.kind = protobuf::EnumOrUnknown::new(resource_wire::MutationKind::MUTATION_KIND_DELETE);
    mutation.target =
        protobuf::MessageField::some(DaemonShellAuthority::shell_resource_identity_with_revision(
            &zone,
            &resource_ref,
            envelope.metadata().uid(),
            envelope.metadata().generation().get(),
            envelope.metadata().revision().get(),
        ));
    let mut precondition = resource_wire::Precondition::new();
    precondition.kind = protobuf::EnumOrUnknown::new(
        resource_wire::PreconditionKind::PRECONDITION_KIND_EXACT_REVISION,
    );
    precondition.expected_revision = Some(envelope.metadata().revision().get());
    mutation.precondition = protobuf::MessageField::some(precondition);
    let mut request = resource_wire::DeleteRequest::new();
    request.meta = protobuf::MessageField::some(DaemonShellAuthority::shell_resource_request_meta(
        "shell-session-kill",
    ));
    request.mutation = protobuf::MessageField::some(mutation);
    let response = block_on_future(client.delete(request));
    if let Some(error) = response.error.as_ref() {
        return Err(shell_resource_api_error(error));
    }
    Ok(public_wire::ShellKillResult {
        name,
        killed: true,
        state: public_wire::ShellSessionState::Killed,
    })
}

fn dispatch_shell_management(
    state: &ServerState,
    peer: &PeerIdentity,
    op: ShellManagementOp,
) -> Result<Value, TypedError> {
    use d2b_contracts_control::unsafe_local_wire::{HelperShellRequest, HelperShellResponse};
    use workload_dispatch::WorkloadRoute;

    if !matches!(peer.role, PeerRole::Admin) {
        return Err(TypedError::AuthzNotAdmin {
            verb: "shell".to_owned(),
        });
    }
    let response = match op {
        ShellManagementOp::List {
            target: requested_target,
        } => {
            let resolved = resolve_shell_target(state, &requested_target).inspect_err(|error| {
                record_unresolved_shell_failure(state, peer.uid, &requested_target, "list", error);
            })?;
            let (result, provider, target, operation_digest) = match resolved.route.clone() {
                WorkloadRoute::LocalVm { vm } => {
                    let result = production_guest_shell_list(state, &vm).inspect_err(|error| {
                        record_shell_dispatch_failure(
                            state,
                            peer.uid,
                            &vm,
                            d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                            "list",
                            None,
                            error,
                        );
                    })?;
                    (
                        result,
                        d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                        vm,
                        None,
                    )
                }
                WorkloadRoute::UnsafeLocal => {
                    let (identity, policy) = unsafe_shell_request_parts(&resolved)?;
                    let operation_id = new_internal_shell_operation_id()?;
                    let operation_digest = shell_ref_digest(&[operation_id.as_str()]);
                    let target = identity.canonical_target.to_canonical();
                    let request = HelperShellRequest::List {
                        request_id: next_internal_shell_request_id(),
                        operation_id,
                        workload: identity,
                        policy,
                    };
                    let response = dispatch_unsafe_shell_management(state, peer.uid, request)
                        .inspect_err(|error| {
                            record_shell_dispatch_failure(
                                state,
                                peer.uid,
                                &target,
                                d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                                "list",
                                Some(operation_digest.clone()),
                                error,
                            );
                        })?;
                    let HelperShellResponse::List(response) = response else {
                        return Err(d2bd_runtime::shell_backend::unsafe_shell_failed(
                            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                        ));
                    };
                    (
                        response.result,
                        d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                        target,
                        Some(operation_digest),
                    )
                }
                WorkloadRoute::CapabilityUnavailable { provider } => {
                    let error = shell_route_capability_error(&requested_target, provider);
                    record_resolved_shell_failure(
                        state,
                        peer.uid,
                        &resolved,
                        &requested_target,
                        "list",
                        None,
                        &error,
                    );
                    return Err(error);
                }
            };
            emit_provider_shell_audit(
                state,
                ProviderShellAudit {
                    target: &target,
                    peer_uid: peer.uid,
                    provider,
                    action: d2bd_runtime::daemon_audit::ShellAuditAction::List,
                    result: d2bd_runtime::daemon_audit::ShellAuditResult::Listed,
                    force: None,
                    operation_digest,
                    session_digest: None,
                },
            );
            shell_metric_for_provider(state, provider, "list", "management", "none");
            serde_json::to_value(result).map_err(|_| shell_protocol_failed())?
        }
        ShellManagementOp::Detach {
            target: requested_target,
            name,
        } => {
            let resolved = resolve_shell_target(state, &requested_target).inspect_err(|error| {
                record_unresolved_shell_failure(
                    state,
                    peer.uid,
                    &requested_target,
                    "detach",
                    error,
                );
            })?;
            let (result, provider, target, operation_digest) = match resolved.route.clone() {
                WorkloadRoute::LocalVm { vm } => {
                    let result = production_guest_shell_detach(state, &vm, name.clone())
                        .inspect_err(|error| {
                            record_shell_dispatch_failure(
                                state,
                                peer.uid,
                                &vm,
                                d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                                "detach",
                                None,
                                error,
                            );
                        })?;
                    (
                        result,
                        d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                        vm,
                        None,
                    )
                }
                WorkloadRoute::UnsafeLocal => {
                    let (identity, policy) = unsafe_shell_request_parts(&resolved)?;
                    let name = name.unwrap_or_else(|| policy.default_name.clone());
                    let operation_id = new_internal_shell_operation_id()?;
                    let operation_digest = shell_ref_digest(&[operation_id.as_str()]);
                    let target = identity.canonical_target.to_canonical();
                    let request = HelperShellRequest::Detach {
                        request_id: next_internal_shell_request_id(),
                        operation_id,
                        workload: identity,
                        policy,
                        name,
                    };
                    let response = dispatch_unsafe_shell_management(state, peer.uid, request)
                        .inspect_err(|error| {
                            record_shell_dispatch_failure(
                                state,
                                peer.uid,
                                &target,
                                d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                                "detach",
                                Some(operation_digest.clone()),
                                error,
                            );
                        })?;
                    let HelperShellResponse::Detach(response) = response else {
                        return Err(d2bd_runtime::shell_backend::unsafe_shell_failed(
                            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                        ));
                    };
                    (
                        response.result,
                        d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                        target,
                        Some(operation_digest),
                    )
                }
                WorkloadRoute::CapabilityUnavailable { provider } => {
                    let error = shell_route_capability_error(&requested_target, provider);
                    record_resolved_shell_failure(
                        state,
                        peer.uid,
                        &resolved,
                        &requested_target,
                        "detach",
                        None,
                        &error,
                    );
                    return Err(error);
                }
            };
            let digest = shell_ref_digest(&[&target, result.resolved_name.as_str()]);
            emit_provider_shell_audit(
                state,
                ProviderShellAudit {
                    target: &target,
                    peer_uid: peer.uid,
                    provider,
                    action: d2bd_runtime::daemon_audit::ShellAuditAction::Detach,
                    result: d2bd_runtime::daemon_audit::ShellAuditResult::Detached,
                    force: None,
                    operation_digest,
                    session_digest: Some(digest),
                },
            );
            shell_metric_for_provider(state, provider, "detach", "management", "none");
            serde_json::to_value(result).map_err(|_| shell_protocol_failed())?
        }
        ShellManagementOp::Kill {
            target: requested_target,
            name: requested_name,
        } => {
            let resolved = resolve_shell_target(state, &requested_target).inspect_err(|error| {
                record_unresolved_shell_failure(state, peer.uid, &requested_target, "kill", error);
            })?;
            let (result, provider, target, operation_digest) = match resolved.route.clone() {
                WorkloadRoute::LocalVm { vm } => {
                    let result = production_guest_shell_kill(state, &vm, requested_name.clone())
                        .inspect_err(|error| {
                            record_shell_dispatch_failure(
                                state,
                                peer.uid,
                                &vm,
                                d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                                "kill",
                                None,
                                error,
                            );
                        })?;
                    (
                        result,
                        d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                        vm,
                        None,
                    )
                }
                WorkloadRoute::UnsafeLocal => {
                    let (identity, policy) = unsafe_shell_request_parts(&resolved)?;
                    let operation_id = new_internal_shell_operation_id()?;
                    let operation_digest = shell_ref_digest(&[operation_id.as_str()]);
                    let target = identity.canonical_target.to_canonical();
                    let request = HelperShellRequest::Kill {
                        request_id: next_internal_shell_request_id(),
                        operation_id,
                        workload: identity,
                        policy,
                        name: requested_name.clone(),
                    };
                    let response = dispatch_unsafe_shell_management(state, peer.uid, request)
                        .inspect_err(|error| {
                            record_shell_dispatch_failure(
                                state,
                                peer.uid,
                                &target,
                                d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                                "kill",
                                Some(operation_digest.clone()),
                                error,
                            );
                        })?;
                    let HelperShellResponse::Kill(response) = response else {
                        return Err(d2bd_runtime::shell_backend::unsafe_shell_failed(
                            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                        ));
                    };
                    (
                        response.result,
                        d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                        target,
                        Some(operation_digest),
                    )
                }
                WorkloadRoute::CapabilityUnavailable { provider } => {
                    let error = shell_route_capability_error(&requested_target, provider);
                    record_resolved_shell_failure(
                        state,
                        peer.uid,
                        &resolved,
                        &requested_target,
                        "kill",
                        None,
                        &error,
                    );
                    return Err(error);
                }
            };
            let digest = shell_ref_digest(&[&target, requested_name.as_str()]);
            emit_provider_shell_audit(
                state,
                ProviderShellAudit {
                    target: &target,
                    peer_uid: peer.uid,
                    provider,
                    action: d2bd_runtime::daemon_audit::ShellAuditAction::Kill,
                    result: d2bd_runtime::daemon_audit::ShellAuditResult::Killed,
                    force: None,
                    operation_digest,
                    session_digest: Some(digest),
                },
            );
            shell_metric_for_provider(state, provider, "kill", "management", "none");
            serde_json::to_value(result).map_err(|_| shell_protocol_failed())?
        }
    };
    Ok(response)
}

fn unsafe_shell_request_parts(
    resolved: &workload_dispatch::ResolvedShell,
) -> Result<
    (
        d2b_core::workload_identity::WorkloadIdentity,
        d2b_contracts_control::unsafe_local_wire::HelperShellPolicy,
    ),
    TypedError,
> {
    let identity = resolved.identity.clone().ok_or_else(|| {
        d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
        )
    })?;
    let policy = resolved.policy.clone().ok_or_else(|| {
        d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
        )
    })?;
    Ok((identity, policy))
}

fn dispatch_unsafe_shell_management(
    state: &ServerState,
    peer_uid: u32,
    request: d2b_contracts_control::unsafe_local_wire::HelperShellRequest,
) -> Result<d2b_contracts_control::unsafe_local_wire::HelperShellResponse, TypedError> {
    match state
        .unsafe_local_helpers
        .dispatch_shell(peer_uid, request)
        .map_err(map_shell_helper_registry_error)?
    {
        d2bd_runtime::unsafe_local_helper::HelperShellReply::Management(response) => Ok(response),
        d2bd_runtime::unsafe_local_helper::HelperShellReply::Terminal { .. } => {
            Err(d2bd_runtime::shell_backend::unsafe_shell_failed(
                d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
            ))
        }
    }
}

fn shell_route_capability_error(
    target: &str,
    provider: d2b_realm_core::WorkloadProviderKind,
) -> TypedError {
    TypedError::RuntimeCapabilityUnsupported {
        vm: target.to_owned(),
        runtime_kind: workload_provider_label(provider).to_owned(),
        capability: "persistent-shell".to_owned(),
        verb: "shell".to_owned(),
    }
}

fn record_shell_dispatch_failure(
    state: &ServerState,
    peer_uid: u32,
    target: &str,
    provider: d2bd_runtime::shell_backend::ShellProvider,
    operation: &'static str,
    operation_digest: Option<String>,
    error: &TypedError,
) {
    shell_metric_for_provider(
        state,
        provider,
        operation,
        "error",
        shell_error_kind_label(error),
    );
    emit_provider_shell_audit(
        state,
        ProviderShellAudit {
            target,
            peer_uid,
            provider,
            action: d2bd_runtime::daemon_audit::ShellAuditAction::Failure,
            result: d2bd_runtime::daemon_audit::ShellAuditResult::Refused,
            force: None,
            operation_digest,
            session_digest: None,
        },
    );
}

fn record_unresolved_shell_failure(
    state: &ServerState,
    peer_uid: u32,
    _requested_target: &str,
    operation: &'static str,
    error: &TypedError,
) {
    let provider = shell_provider_for_error(error);
    shell_metric_for_provider(
        state,
        provider,
        operation,
        "error",
        shell_error_kind_label(error),
    );
    emit_shell_failure_audit(state, peer_uid, _requested_target, error);
}

fn record_resolved_shell_failure(
    state: &ServerState,
    peer_uid: u32,
    resolved: &workload_dispatch::ResolvedShell,
    _requested_target: &str,
    operation: &'static str,
    operation_digest: Option<String>,
    error: &TypedError,
) {
    use workload_dispatch::WorkloadRoute;

    let (provider, target) = match &resolved.route {
        WorkloadRoute::UnsafeLocal => (
            d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
            resolved
                .identity
                .as_ref()
                .map(|identity| identity.canonical_target.to_canonical())
                .unwrap_or_else(|| unresolved_shell_audit_target().to_owned()),
        ),
        WorkloadRoute::LocalVm { vm } => (
            d2bd_runtime::shell_backend::ShellProvider::GuestControl,
            vm.clone(),
        ),
        WorkloadRoute::CapabilityUnavailable { provider } => (
            if *provider == d2b_realm_core::WorkloadProviderKind::UnsafeLocal {
                d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal
            } else {
                d2bd_runtime::shell_backend::ShellProvider::GuestControl
            },
            resolved
                .identity
                .as_ref()
                .map(|identity| identity.canonical_target.to_canonical())
                .unwrap_or_else(|| unresolved_shell_audit_target().to_owned()),
        ),
    };
    record_shell_dispatch_failure(
        state,
        peer_uid,
        &target,
        provider,
        operation,
        operation_digest,
        error,
    );
}

fn shell_audit_provider(
    provider: d2bd_runtime::shell_backend::ShellProvider,
) -> d2bd_runtime::daemon_audit::ShellAuditProvider {
    match provider {
        d2bd_runtime::shell_backend::ShellProvider::GuestControl => {
            d2bd_runtime::daemon_audit::ShellAuditProvider::GuestControl
        }
        d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal => {
            d2bd_runtime::daemon_audit::ShellAuditProvider::UnsafeLocal
        }
    }
}

struct ProviderShellAudit<'a> {
    target: &'a str,
    peer_uid: u32,
    provider: d2bd_runtime::shell_backend::ShellProvider,
    action: d2bd_runtime::daemon_audit::ShellAuditAction,
    result: d2bd_runtime::daemon_audit::ShellAuditResult,
    force: Option<bool>,
    operation_digest: Option<String>,
    session_digest: Option<String>,
}

fn emit_provider_shell_audit(state: &ServerState, event: ProviderShellAudit<'_>) {
    let _ =
        state
            .daemon_audit
            .write_event(&d2bd_runtime::daemon_audit::DaemonEvent::ShellLifecycle {
                target: event.target.to_owned(),
                peer_uid: event.peer_uid,
                provider: shell_audit_provider(event.provider),
                action: event.action,
                result: event.result,
                force: event.force,
                operation_digest: event.operation_digest,
                session_digest: event.session_digest,
            });
}

fn emit_shell_attach_audit(
    state: &ServerState,
    peer_uid: u32,
    established: &d2bd_runtime::shell_backend::EstablishedShell,
    shell_ref_digest: &str,
    force: bool,
) {
    emit_provider_shell_audit(
        state,
        ProviderShellAudit {
            target: &established.target,
            peer_uid,
            provider: established.provider,
            action: d2bd_runtime::daemon_audit::ShellAuditAction::Attach,
            result: d2bd_runtime::daemon_audit::ShellAuditResult::Attached,
            force: Some(force),
            operation_digest: established.operation_digest.clone(),
            session_digest: Some(shell_ref_digest.to_owned()),
        },
    );
}

fn emit_shell_close_audit(
    state: &ServerState,
    peer_uid: u32,
    established: &d2bd_runtime::shell_backend::EstablishedShell,
    result: d2bd_runtime::daemon_audit::ShellAuditResult,
    shell_ref_digest: &str,
) {
    emit_provider_shell_audit(
        state,
        ProviderShellAudit {
            target: &established.target,
            peer_uid,
            provider: established.provider,
            action: d2bd_runtime::daemon_audit::ShellAuditAction::Close,
            result,
            force: None,
            operation_digest: established.operation_digest.clone(),
            session_digest: Some(shell_ref_digest.to_owned()),
        },
    );
}

fn emit_shell_failure_audit(
    state: &ServerState,
    peer_uid: u32,
    _requested_target: &str,
    error: &TypedError,
) {
    let provider = shell_provider_for_error(error);
    let target = unresolved_shell_audit_target();
    emit_provider_shell_audit(
        state,
        ProviderShellAudit {
            target,
            peer_uid,
            provider,
            action: d2bd_runtime::daemon_audit::ShellAuditAction::Failure,
            result: d2bd_runtime::daemon_audit::ShellAuditResult::Refused,
            force: None,
            operation_digest: None,
            session_digest: None,
        },
    );
}

fn unresolved_shell_audit_target() -> &'static str {
    "unresolved"
}

fn typed_shell_request(request: &Value) -> bool {
    matches!(
        request.get("method").and_then(Value::as_str),
        Some("Create" | "Attach")
    ) && (request.get("resourceType").and_then(Value::as_str)
        == Some("shell-terminal.d2bus.org.ShellSession")
        || request
            .get("resourceRef")
            .and_then(Value::as_str)
            .is_some_and(is_typed_shell_resource_ref))
}

fn is_typed_shell_resource_ref(value: &str) -> bool {
    value.starts_with("shell-terminal.d2bus.org.ShellSession/")
}

fn typed_shell_resource_name(resource: &str) -> Result<public_wire::ShellName, TypedError> {
    resource
        .strip_prefix("shell-terminal.d2bus.org.ShellSession/")
        .and_then(|name| public_wire::ShellName::new(name).ok())
        .ok_or_else(shell_protocol_failed)
}

fn typed_shell_execution_target(value: &str) -> Result<String, TypedError> {
    let execution_ref = d2b_contracts_resource::v3::ResourceRef::parse(value)
        .map_err(|_| shell_protocol_failed())?;
    match execution_ref.resource_type().as_str() {
        "Host" => Ok(format!("{}.host.d2b", execution_ref.name().as_str())),
        "Guest" => Ok(execution_ref.name().as_str().to_owned()),
        _ => Err(shell_protocol_failed()),
    }
}

fn guest_shell_session(
    state: &ServerState,
    vm: &str,
    name: &public_wire::ShellName,
) -> Result<(ShellPool, ShellSession), TypedError> {
    let resolver = load_bundle_resolver(state)?;
    let entry =
        resolver
            .manifest
            .vms
            .get(vm)
            .ok_or_else(|| TypedError::WorkloadTargetNotFound {
                target: vm.to_owned(),
            })?;
    let shell = entry
        .shell
        .as_ref()
        .filter(|shell| shell.enabled)
        .ok_or_else(shell_capability_failed)?;
    let workload_user = entry
        .ssh_user
        .as_deref()
        .ok_or_else(shell_capability_failed)?;
    let pool_name = format!("{vm}-shell");
    let pool = ShellPool::new(
        pool_name,
        "local-root",
        PoolSpec::new(
            ExecutionTarget::guest(vm.to_owned()),
            workload_user,
            "artifact://shells/bash-login",
            shell.max_sessions,
            shell.max_attached,
            DEFAULT_OUTPUT_RING_CAPACITY,
        )
        .map_err(|_| shell_protocol_failed())?,
    )
    .map_err(|_| shell_protocol_failed())?;
    let session =
        ShellSession::from_pool_with_resource_name(&pool, name.as_str(), name.as_str(), None)
            .map_err(|_| shell_protocol_failed())?;
    Ok((pool, session))
}

fn shell_session_from_resource(
    envelope: &d2b_contracts_resource::v3::ResourceEnvelope,
) -> Result<ShellSession, TypedError> {
    if envelope.resource_type().as_str() != "shell-terminal.d2bus.org.ShellSession" {
        return Err(shell_protocol_failed());
    }
    let spec = serde_json::from_slice::<Value>(&envelope.spec().base().to_canonical_bytes())
        .map_err(|_| shell_protocol_failed())?;
    let execution_ref = spec
        .get("executionRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| matches!(value.resource_type().as_str(), "Host" | "Guest"))
        .ok_or_else(shell_protocol_failed)?;
    let user_ref = spec
        .get("userRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "User")
        .ok_or_else(shell_protocol_failed)?;
    let pool_name = spec
        .get("poolRef")
        .and_then(Value::as_str)
        .and_then(|value| ResourceRef::parse(value).ok())
        .filter(|value| value.resource_type().as_str() == "shell-terminal.d2bus.org.ShellPool")
        .map(|value| value.name().as_str().to_owned())
        .unwrap_or_else(|| "shell".to_owned());
    let login_shell_ref = spec
        .get("loginShellRef")
        .and_then(Value::as_str)
        .ok_or_else(shell_protocol_failed)?;
    let target = if execution_ref.resource_type().as_str() == "Host" {
        ExecutionTarget::host(execution_ref.name().as_str().to_owned())
    } else {
        ExecutionTarget::guest(execution_ref.name().as_str().to_owned())
    };
    let pool = ShellPool::new(
        pool_name,
        envelope.metadata().zone().as_str(),
        PoolSpec::new(
            target,
            user_ref.name().as_str().to_owned(),
            login_shell_ref.to_owned(),
            spec.get("maxSessions")
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok())
                .unwrap_or(8),
            spec.get("maxAttached")
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok())
                .unwrap_or(1),
            spec.get("outputRingCapacity")
                .and_then(Value::as_u64)
                .unwrap_or(DEFAULT_OUTPUT_RING_CAPACITY),
        )
        .map_err(|_| shell_protocol_failed())?,
    )
    .map_err(|_| shell_protocol_failed())?;
    let session_name = spec
        .get("sessionName")
        .and_then(Value::as_str)
        .unwrap_or(envelope.metadata().name().as_str());
    ShellSession::from_pool_with_resource_name(
        &pool,
        envelope.metadata().name().as_str(),
        session_name,
        spec.get("outputRingCapacity").and_then(Value::as_u64),
    )
    .map_err(|_| shell_protocol_failed())
}

fn configured_shell_targets(state: &ServerState) -> Result<Vec<String>, TypedError> {
    let resolver = load_bundle_resolver(state)?;
    let mut targets = std::collections::BTreeSet::new();
    if let Some(private) = resolver.unsafe_local_workloads.as_ref() {
        targets.extend(
            private
                .workloads
                .iter()
                .filter(|workload| workload.shell.is_some())
                .map(|workload| workload.identity.canonical_target.to_canonical()),
        );
    }
    targets.extend(
        resolver
            .manifest
            .vms
            .iter()
            .filter(|(_, vm)| vm.shell.as_ref().is_some_and(|shell| shell.enabled))
            .map(|(name, _)| name.clone()),
    );
    Ok(targets.into_iter().collect())
}

fn list_typed_shell_target(
    state: &ServerState,
    peer: &PeerIdentity,
    target: String,
) -> Result<public_wire::ShellListResult, TypedError> {
    let value = dispatch_shell_management(state, peer, ShellManagementOp::List { target })?;
    serde_json::from_value(value).map_err(|_| shell_protocol_failed())
}

fn list_configured_typed_shell_targets(
    state: &ServerState,
    peer: &PeerIdentity,
) -> Result<Vec<(String, public_wire::ShellListResult)>, TypedError> {
    let listings = configured_shell_targets(state)?
        .into_iter()
        .map(|target| {
            let result = list_typed_shell_target(state, peer, target.clone())?;
            Ok((target, result))
        })
        .collect::<Result<Vec<_>, TypedError>>()?;
    let bindings = listings
        .iter()
        .flat_map(|(target, result)| {
            result
                .sessions
                .iter()
                .map(move |session| (session.name.clone(), target.clone()))
        })
        .collect::<Vec<_>>();
    cache_unambiguous_typed_shell_session_targets(state, peer.uid, &bindings)?;
    Ok(listings)
}

fn list_typed_shell_sessions_for_target(
    state: &ServerState,
    peer: &PeerIdentity,
    target: &str,
) -> Result<Value, TypedError> {
    let result = list_typed_shell_target(state, peer, target.to_owned())?;
    let bindings = result
        .sessions
        .iter()
        .map(|session| (session.name.clone(), target.to_owned()))
        .collect::<Vec<_>>();
    cache_target_local_typed_shell_session_targets(state, peer.uid, &bindings)?;
    serde_json::to_value(result).map_err(|_| shell_protocol_failed())
}

fn remember_typed_shell_session_target(
    state: &ServerState,
    peer_uid: u32,
    name: &public_wire::ShellName,
    target: &str,
) {
    if let Ok(mut sessions) = state.typed_shell_session_targets.lock() {
        sessions.remember((peer_uid, name.as_str().to_owned()), target.to_owned());
    }
}

fn forget_typed_shell_session_target(
    state: &ServerState,
    peer_uid: u32,
    name: &public_wire::ShellName,
) {
    if let Ok(mut sessions) = state.typed_shell_session_targets.lock() {
        sessions.forget(&(peer_uid, name.as_str().to_owned()));
    }
}

fn cache_unambiguous_typed_shell_session_targets(
    state: &ServerState,
    peer_uid: u32,
    bindings: &[(public_wire::ShellName, String)],
) -> Result<(), TypedError> {
    let mut unique = BTreeMap::new();
    let mut conflicts = BTreeSet::new();
    for (name, target) in bindings {
        let name = name.as_str().to_owned();
        if conflicts.contains(&name) {
            continue;
        }
        if unique.insert(name.clone(), target.clone()).is_some() {
            unique.remove(&name);
            conflicts.insert(name);
        }
    }
    if let Ok(mut sessions) = state.typed_shell_session_targets.lock() {
        for name in &conflicts {
            sessions.forget(&(peer_uid, name.clone()));
        }
        for (name, target) in unique {
            sessions.remember((peer_uid, name), target);
        }
    }
    if let Some(workload_id) = conflicts.into_iter().next() {
        return Err(TypedError::WorkloadAliasConflict {
            workload_id,
            detail: "ShellSession name exists on more than one execution target".to_owned(),
        });
    }
    Ok(())
}

fn cache_target_local_typed_shell_session_targets(
    state: &ServerState,
    peer_uid: u32,
    bindings: &[(public_wire::ShellName, String)],
) -> Result<(), TypedError> {
    let mut names = BTreeSet::new();
    for (name, _) in bindings {
        if !names.insert(name.as_str().to_owned()) {
            forget_typed_shell_session_target(state, peer_uid, name);
            return Err(TypedError::WorkloadAliasConflict {
                workload_id: name.as_str().to_owned(),
                detail:
                    "ShellSession name appears more than once on the requested execution target"
                        .to_owned(),
            });
        }
    }
    for (name, target) in bindings {
        remember_typed_shell_session_target(state, peer_uid, name, target);
    }
    Ok(())
}

fn cached_typed_shell_session_target(
    state: &ServerState,
    peer_uid: u32,
    name: &public_wire::ShellName,
) -> Option<String> {
    state
        .typed_shell_session_targets
        .lock()
        .ok()
        .and_then(|mut sessions| sessions.cached(&(peer_uid, name.as_str().to_owned())))
}

fn reserve_typed_shell_session_create(
    state: &ServerState,
    peer_uid: u32,
    name: &public_wire::ShellName,
) -> Result<d2bd_runtime::typed_shell_targets::TypedShellSessionCreateReservation, TypedError> {
    let key = (peer_uid, name.as_str().to_owned());
    d2bd_runtime::typed_shell_targets::TypedShellSessionTargetCache::reserve(
        &state.typed_shell_session_targets,
        key,
    )
    .ok_or_else(|| TypedError::WorkloadAliasConflict {
        workload_id: name.as_str().to_owned(),
        detail: "ShellSession name is already being created".to_owned(),
    })
}

#[cfg(test)]
fn typed_shell_session_target_cache_len(state: &ServerState) -> usize {
    state
        .typed_shell_session_targets
        .lock()
        .map(|sessions| sessions.len())
        .unwrap_or(0)
}

#[cfg(test)]
fn typed_shell_session_target_cache_recency_len(state: &ServerState) -> usize {
    state
        .typed_shell_session_targets
        .lock()
        .map(|sessions| sessions.recency_len())
        .unwrap_or(0)
}

fn find_typed_shell_session_target(
    state: &ServerState,
    peer: &PeerIdentity,
    name: &public_wire::ShellName,
) -> Result<Option<String>, TypedError> {
    let listings = list_configured_typed_shell_targets(state, peer)?;
    find_typed_shell_session_target_in_listings(state, peer.uid, name, &listings)
}

fn find_typed_shell_session_target_in_listings(
    state: &ServerState,
    peer_uid: u32,
    name: &public_wire::ShellName,
    listings: &[(String, public_wire::ShellListResult)],
) -> Result<Option<String>, TypedError> {
    let mut matched = None;
    for (target, result) in listings {
        if result.sessions.iter().any(|session| session.name == *name) {
            if matched.is_some() {
                // The complete listing helper validates this before returning.
                // Keep this guard local so a future caller cannot accidentally
                // route an ambiguous name if that helper changes.
                forget_typed_shell_session_target(state, peer_uid, name);
                return Err(TypedError::WorkloadAliasConflict {
                    workload_id: name.as_str().to_owned(),
                    detail: "ShellSession name exists on more than one execution target".to_owned(),
                });
            }
            matched = Some(target.clone());
        }
    }
    if let Some(target) = matched.as_deref() {
        remember_typed_shell_session_target(state, peer_uid, name, target);
    }
    Ok(matched)
}

fn resolve_typed_shell_session_target(
    state: &ServerState,
    peer: &PeerIdentity,
    resource: &str,
) -> Result<String, TypedError> {
    let name = typed_shell_resource_name(resource)?;
    if let Some(target) = find_typed_shell_session_target(state, peer, &name)? {
        return Ok(target);
    }
    if let Some(target) = cached_typed_shell_session_target(state, peer.uid, &name) {
        return Ok(target);
    }
    Err(TypedError::WorkloadTargetNotFound {
        target: resource.to_owned(),
    })
}

fn spawn_typed_shell_owner(
    stream: Socket,
    state: ServerState,
    peer: PeerIdentity,
    request: Value,
    permit: Option<d2bd_runtime::concurrency::ConnPermit>,
) -> io::Result<thread::JoinHandle<()>> {
    thread::Builder::new()
        .name("d2b-typed-shell-owner".to_owned())
        .spawn(move || {
            run_typed_shell_owner(stream, state, peer, request, permit);
        })
}

fn process_stream_response(
    runtime: &tokio::runtime::Handle,
    client: &dyn exec_session::ExecGuestClient,
    request: public_wire::NamedProcessStreamRequest,
    control_sequence: &mut u64,
) -> Result<(public_wire::NamedProcessStreamResponse, bool), exec_session::ExecOpError> {
    use d2bd_runtime::terminal_session::OutputStreamSel;
    match request {
        public_wire::NamedProcessStreamRequest::Stdin {
            offset,
            chunk_base64,
            eof,
        } => {
            let data = d2b_core::base64_codec::decode(&chunk_base64)
                .map_err(|_| exec_session::ExecOpError::Protocol)?;
            let result = runtime.block_on(client.write_stdin(
                offset,
                data,
                eof,
                SHELL_MANAGEMENT_TIMEOUT,
            ))?;
            Ok((
                public_wire::NamedProcessStreamResponse::Stdin(public_wire::ExecWriteStdinResult {
                    accepted_len: result.accepted_len,
                    next_offset: result.next_offset,
                    backpressured: result.backpressured,
                    stdin_closed: result.stdin_closed,
                }),
                false,
            ))
        }
        public_wire::NamedProcessStreamRequest::Read {
            stream,
            offset,
            max_len,
            wait,
            timeout_ms,
        } => {
            let result = runtime.block_on(client.read_output(
                match stream {
                    public_wire::ExecStream::Stdout => OutputStreamSel::Stdout,
                    public_wire::ExecStream::Stderr => OutputStreamSel::Stderr,
                },
                offset,
                max_len,
                wait,
                timeout_ms,
                SHELL_MANAGEMENT_TIMEOUT,
            ))?;
            Ok((
                public_wire::NamedProcessStreamResponse::Output(
                    public_wire::ExecReadOutputResult {
                        data_base64: d2b_core::base64_codec::encode(&result.data),
                        next_offset: result.next_offset,
                        eof: result.eof,
                        dropped_bytes: result.dropped_bytes,
                        truncated: result.truncated,
                        timed_out: result.timed_out,
                    },
                ),
                false,
            ))
        }
        public_wire::NamedProcessStreamRequest::Signal { control_seq, signo } => {
            if control_seq == 0 || control_seq <= *control_sequence {
                return Err(exec_session::ExecOpError::OldGeneration);
            }
            runtime.block_on(client.signal(control_seq, signo, SHELL_MANAGEMENT_TIMEOUT))?;
            *control_sequence = control_seq;
            Ok((
                public_wire::NamedProcessStreamResponse::Delivered(
                    public_wire::ExecControlResult { delivered: true },
                ),
                false,
            ))
        }
        public_wire::NamedProcessStreamRequest::Resize {
            control_seq,
            rows,
            cols,
        } => {
            if control_seq == 0 || control_seq <= *control_sequence {
                return Err(exec_session::ExecOpError::OldGeneration);
            }
            runtime.block_on(client.resize(control_seq, rows, cols, SHELL_MANAGEMENT_TIMEOUT))?;
            *control_sequence = control_seq;
            Ok((
                public_wire::NamedProcessStreamResponse::Delivered(
                    public_wire::ExecControlResult { delivered: true },
                ),
                false,
            ))
        }
        public_wire::NamedProcessStreamRequest::CloseStdin { offset } => {
            runtime.block_on(client.close_stdin(offset, SHELL_MANAGEMENT_TIMEOUT))?;
            Ok((
                public_wire::NamedProcessStreamResponse::Closed(public_wire::ExecCloseResult {
                    stdin_closed: true,
                }),
                false,
            ))
        }
        public_wire::NamedProcessStreamRequest::Wait { timeout_ms } => {
            let result = runtime.block_on(client.wait(timeout_ms, SHELL_MANAGEMENT_TIMEOUT))?;
            let terminal_status = result.terminal.map(|terminal| match terminal {
                d2bd_runtime::terminal_session::TerminalKind::Exited(code) => {
                    public_wire::ExecTerminalStatus::Exited { code }
                }
                d2bd_runtime::terminal_session::TerminalKind::Signaled(signal) => {
                    public_wire::ExecTerminalStatus::Signaled { signal }
                }
                d2bd_runtime::terminal_session::TerminalKind::Error(slug) => {
                    public_wire::ExecTerminalStatus::Error {
                        slug: slug.to_owned(),
                    }
                }
            });
            Ok((
                public_wire::NamedProcessStreamResponse::Wait(public_wire::ExecWaitResult {
                    running: result.running,
                    terminal_status,
                }),
                false,
            ))
        }
        public_wire::NamedProcessStreamRequest::Cancel => {
            runtime.block_on(client.cancel(0, SHELL_MANAGEMENT_TIMEOUT))?;
            Ok((
                public_wire::NamedProcessStreamResponse::Closed(public_wire::ExecCloseResult {
                    stdin_closed: true,
                }),
                true,
            ))
        }
        public_wire::NamedProcessStreamRequest::Close => {
            runtime.block_on(client.cancel(0, SHELL_MANAGEMENT_TIMEOUT))?;
            Ok((
                public_wire::NamedProcessStreamResponse::Closed(public_wire::ExecCloseResult {
                    stdin_closed: true,
                }),
                true,
            ))
        }
    }
}

fn run_process_resource_owner(
    stream: Socket,
    state: ServerState,
    peer: PeerIdentity,
    request: Value,
    _conn_permit: Option<d2bd_runtime::concurrency::ConnPermit>,
) {
    #[cfg(test)]
    {
        if let Some(hook) = owner_connection_test_hook::active() {
            hook();
            drop(stream);
            return;
        }
    }
    let (vm, execution_ref) = match if request.get("executionRef").is_some() {
        process_resource_execution_ref(&request)
    } else {
        process_resource_execution_ref_from_resource(&state, &request)
    } {
        Ok(value) => value,
        Err(error) => {
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
            return;
        }
    };
    let _slot = match state.exec_sessions.reserve(peer.uid, &vm) {
        Ok(slot) => slot,
        Err(error) => {
            let error = map_exec_reserve_error(error);
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
            return;
        }
    };
    let spec = exec_session::ExecStartSpec {
        vm: vm.clone(),
        request_id: request
            .get("opId")
            .and_then(Value::as_u64)
            .map(|value| value.to_string()),
        argv: request
            .get("argv")
            .and_then(Value::as_array)
            .map(|argv| {
                argv.iter()
                    .filter_map(Value::as_str)
                    .map(ToOwned::to_owned)
                    .collect()
            })
            .unwrap_or_default(),
        tty: request.get("tty").and_then(Value::as_bool).unwrap_or(false),
        detached: request
            .get("detached")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        env: Vec::new(),
        cwd: request
            .get("cwd")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned),
        term_size: request
            .get("initialSize")
            .and_then(Value::as_object)
            .and_then(|size| {
                size.get("rows")
                    .and_then(Value::as_u64)
                    .zip(size.get("cols").and_then(Value::as_u64))
                    .map(|(rows, cols)| (rows as u32, cols as u32))
            }),
    };
    let resource_ref = process_resource_ref(&request);
    let Some(resource_ref) = resource_ref else {
        let error = TypedError::GuestControlExecFailed {
            kind: d2bd_runtime::typed_error::GuestControlExecErrorKind::Protocol,
        };
        let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
        return;
    };
    let connector = match exec_session_real::ResourceExecConnector::new(
        production_process_resource_port(&state, &request, &execution_ref),
        execution_ref,
    ) {
        Ok(connector) => connector,
        Err(error) => {
            let error = map_resource_exec_error(establish_error_as_exec_error(error), &vm);
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
            return;
        }
    };
    let rt = match tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
    {
        Ok(rt) => rt,
        Err(_) => {
            let error = TypedError::GuestControlExecFailed {
                kind: d2bd_runtime::typed_error::GuestControlExecErrorKind::Internal,
            };
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
            return;
        }
    };
    let established = match rt.block_on(connector.establish(&spec)) {
        Ok(established) => established,
        Err(error) => {
            let error = map_resource_exec_error(establish_error_as_exec_error(error), &vm);
            let _ = write_json_frame(&stream, &d2bd_runtime::wire::error_frame(&error));
            return;
        }
    };
    let initial = serde_json::json!({
        "attached": true,
        "resourceRef": resource_ref.to_canonical_string(),
        "tty": spec.tty,
    });
    if write_json_frame(&stream, &initial).is_err() {
        let _ = rt.block_on(established.client.cancel(
            established.control_seq.saturating_add(1),
            SHELL_MANAGEMENT_TIMEOUT,
        ));
        return;
    }
    let mut control_sequence = established.control_seq;
    let client = established.client;
    while let Ok(frame) = read_frame(&stream) {
        let request: public_wire::NamedProcessStreamRequestFrame =
            match serde_json::from_slice(&frame) {
                Ok(request) => request,
                Err(_) => {
                    let _ = write_named_process_stream_error(&stream, 0, shell_protocol_failed());
                    break;
                }
            };
        let request_id = request.request_id;
        let result = process_stream_response(
            rt.handle(),
            client.as_ref(),
            request.request,
            &mut control_sequence,
        );
        let (response, terminal) = match result {
            Ok(result) => result,
            Err(error) => {
                let typed = map_resource_exec_error(error, &vm);
                let _ = write_named_process_stream_error(&stream, request_id, typed);
                continue;
            }
        };
        let frame = public_wire::NamedProcessStreamResponseFrame::new(request_id, response);
        if write_json_frame(
            &stream,
            &serde_json::to_value(frame).unwrap_or_else(|_| serde_json::json!({})),
        )
        .is_err()
        {
            break;
        }
        if terminal {
            break;
        }
    }
    let _ =
        rt.block_on(client.cancel(control_sequence.saturating_add(1), SHELL_MANAGEMENT_TIMEOUT));
}

fn run_typed_shell_owner(
    stream: Socket,
    state: ServerState,
    peer: PeerIdentity,
    request: Value,
    // Admission permit held for the lifetime of the typed-shell owner
    // connection so the in-flight slot is released only on owner exit.
    _conn_permit: Option<d2bd_runtime::concurrency::ConnPermit>,
) {
    #[cfg(test)]
    {
        if let Some(hook) = owner_connection_test_hook::active() {
            hook();
            drop(stream);
            return;
        }
    }
    let rt = match tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
    {
        Ok(rt) => rt,
        Err(_) => {
            let _ = write_json_frame(
                &stream,
                &typed_shell_resource_error_frame(&shell_transport_failed()),
            );
            return;
        }
    };
    let method = request.get("method").and_then(Value::as_str).unwrap_or("");
    let Some(resource) = request
        .get("resourceRef")
        .and_then(Value::as_str)
        .map(str::to_owned)
        .or_else(|| {
            request
                .get("name")
                .and_then(Value::as_str)
                .map(|name| format!("shell-terminal.d2bus.org.ShellSession/{name}"))
        })
    else {
        let _ = write_json_frame(
            &stream,
            &typed_shell_resource_error_frame(&shell_protocol_failed()),
        );
        return;
    };
    let name = match typed_shell_resource_name(&resource) {
        Ok(name) => name,
        Err(error) => {
            let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
            return;
        }
    };
    let creating = method == "Create";
    let (target, create_reservation) = if creating {
        let Some(execution_ref) = request.get("executionRef").and_then(Value::as_str) else {
            let _ = write_json_frame(
                &stream,
                &typed_shell_resource_error_frame(&shell_protocol_failed()),
            );
            return;
        };
        let target = match typed_shell_execution_target(execution_ref) {
            Ok(target) => target,
            Err(error) => {
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        };
        let create_reservation = match reserve_typed_shell_session_create(&state, peer.uid, &name) {
            Ok(reservation) => reservation,
            Err(error) => {
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        };
        match find_typed_shell_session_target(&state, &peer, &name) {
            Ok(Some(existing_target)) if existing_target != target => {
                let _ = write_json_frame(
                    &stream,
                    &typed_shell_resource_error_frame(&TypedError::WorkloadAliasConflict {
                        workload_id: name.as_str().to_owned(),
                        detail: "ShellSession name belongs to another execution target".to_owned(),
                    }),
                );
                return;
            }
            Ok(_) => {}
            Err(error) => {
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        }
        (target, Some(create_reservation))
    } else {
        let target = match resolve_typed_shell_session_target(&state, &peer, &resource) {
            Ok(target) => target,
            Err(error) => {
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        };
        (target, None)
    };
    let attach_stream = request
        .get("attach")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let size = request
        .get("initialSize")
        .cloned()
        .and_then(|value| serde_json::from_value(value).ok())
        .unwrap_or(d2b_contracts_control::terminal_wire::TerminalSize { rows: 24, cols: 80 });
    let attach = public_wire::ShellAttachArgs {
        vm: target.clone(),
        name: Some(name.clone()),
        force: request
            .get("force")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        initial_terminal_size: size,
    };
    if matches!(
        resolve_shell_target(&state, &target)
            .map(|resolved| resolved.route)
            .as_ref(),
        Ok(workload_dispatch::WorkloadRoute::LocalVm { .. })
    ) {
        let (pool, session) = match guest_shell_session(&state, &target, &name) {
            Ok(value) => value,
            Err(error) => {
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        };
        let authority = daemon_shell_authority(&state);
        let session_created = match authority.ensure_shell_resources(&pool, &session) {
            Ok(created) => created,
            Err(error) => {
                let error = map_shell_authority_error(error);
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        };
        if creating && session_created {
            if let Err(error) = authority.restore_pool(&pool, 0) {
                let error = map_shell_authority_error(error);
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
            if let Err(error) = authority.open_session(&session) {
                let error = map_shell_authority_error(error);
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        }
        if let Err(error) = authority.ensure_supervisor_process_resource(&session) {
            let error = map_shell_authority_error(error);
            let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
            return;
        }
    }
    let established = match rt.block_on(establish_shell_backend(
        &state,
        peer.uid,
        broker_caller_role_for_peer(&peer),
        &attach,
        production_component_session_driver(&state, &target),
    )) {
        Ok(value) => value,
        Err(error) => {
            tracing::warn!(
                operation = method,
                error_kind = error.kind(),
                "typed shell attachment refused"
            );
            let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
            return;
        }
    };
    remember_typed_shell_session_target(&state, peer.uid, &name, &target);
    drop(create_reservation);
    let session = established.attach.session.clone();
    let owner_shell_ref_digest = shell_ref_digest(&[
        &established.target,
        established.attach.resolved_name.as_str(),
    ]);
    let resolved_name = established.attach.resolved_name.clone();
    let is_default = resolved_name.as_str() == "primary";
    let force_evicted = established.attach.force_evicted;
    let attached_state = established.attach.state;
    if !attach_stream {
        emit_shell_attach_audit(
            &state,
            peer.uid,
            &established,
            &owner_shell_ref_digest,
            attach.force,
        );
        shell_metric_for_provider(
            &state,
            established.provider,
            "attach",
            "established",
            "none",
        );
        let mut control_sequence = established.initial_control_sequence;
        let close_result = match established
            .backend
            .close_attachment(rt.handle(), &mut control_sequence)
        {
            Ok(_) => d2bd_runtime::daemon_audit::ShellAuditResult::Closed,
            Err(error) => {
                let _ = write_json_frame(&stream, &typed_shell_resource_error_frame(&error));
                return;
            }
        };
        emit_shell_close_audit(
            &state,
            peer.uid,
            &established,
            close_result,
            &owner_shell_ref_digest,
        );
        shell_metric_for_provider(&state, established.provider, "close", "closed", "none");
        let _ = write_json_frame(
            &stream,
            &json!({
                "attached": false,
                "resourceRef": resource,
                "status": {
                    "name": resolved_name,
                    "state": public_wire::ShellSessionState::Detached,
                    "attached": false,
                    "isDefault": is_default,
                    "forceEvicted": force_evicted,
                },
            }),
        );
        return;
    }
    if write_json_frame(
        &stream,
        &json!({
            "attached": true,
            "resourceRef": resource,
            "status": {
                "name": resolved_name,
                "state": attached_state,
                "attached": true,
                "isDefault": is_default,
                "forceEvicted": force_evicted,
            },
        }),
    )
    .is_err()
    {
        let mut control_sequence = established.initial_control_sequence;
        d2bd_runtime::shell_backend::best_effort_cancel(
            established.backend.as_ref(),
            rt.handle(),
            &mut control_sequence,
        );
        let error = shell_transport_failed();
        record_shell_dispatch_failure(
            &state,
            peer.uid,
            &established.target,
            established.provider,
            "attach",
            established.operation_digest.clone(),
            &error,
        );
        return;
    }
    emit_shell_attach_audit(
        &state,
        peer.uid,
        &established,
        &owner_shell_ref_digest,
        attach.force,
    );
    shell_metric_for_provider(
        &state,
        established.provider,
        "attach",
        "established",
        "none",
    );
    let mut control_sequence = established.initial_control_sequence;
    let mut close_result = None;
    while let Ok(frame) = read_frame(&stream) {
        let request: public_wire::NamedProcessStreamRequestFrame =
            match serde_json::from_slice(&frame) {
                Ok(request) => request,
                Err(_) => {
                    let _ = write_named_process_stream_error(
                        &stream,
                        0,
                        d2bd_runtime::shell_backend::shell_protocol_failed(),
                    );
                    break;
                }
            };
        let request_id = request.request_id;
        let close_stdin = matches!(
            &request.request,
            public_wire::NamedProcessStreamRequest::CloseStdin { .. }
        );
        let close = matches!(
            &request.request,
            public_wire::NamedProcessStreamRequest::Close
                | public_wire::NamedProcessStreamRequest::Cancel
        );
        if close {
            let result = established
                .backend
                .close_attachment(rt.handle(), &mut control_sequence);
            match result {
                Ok(_) => {
                    close_result = Some(d2bd_runtime::daemon_audit::ShellAuditResult::Closed);
                    let response = public_wire::NamedProcessStreamResponseFrame::new(
                        request_id,
                        public_wire::NamedProcessStreamResponse::Closed(
                            public_wire::ExecCloseResult { stdin_closed: true },
                        ),
                    );
                    let _ = write_json_frame(
                        &stream,
                        &serde_json::to_value(response).unwrap_or_else(|_| json!({})),
                    );
                }
                Err(error) => {
                    close_result = Some(d2bd_runtime::daemon_audit::ShellAuditResult::Refused);
                    let _ = write_named_process_stream_error(&stream, request_id, error);
                }
            }
            break;
        }
        let op = match request.request {
            public_wire::NamedProcessStreamRequest::Stdin {
                offset,
                chunk_base64,
                eof,
            } => {
                if d2b_core::base64_codec::decode(&chunk_base64).is_err() {
                    let _ = write_named_process_stream_error(
                        &stream,
                        request_id,
                        shell_protocol_failed(),
                    );
                    continue;
                }
                d2bd_runtime::shell_backend::ShellTerminalOp::WriteStdin(
                    d2b_contracts_control::terminal_wire::TerminalWriteStdin {
                        session: session.clone(),
                        offset,
                        chunk_base64,
                        eof,
                    },
                )
            }
            public_wire::NamedProcessStreamRequest::CloseStdin { offset } => {
                d2bd_runtime::shell_backend::ShellTerminalOp::WriteStdin(
                    d2b_contracts_control::terminal_wire::TerminalWriteStdin {
                        session: session.clone(),
                        offset,
                        chunk_base64: String::new(),
                        eof: true,
                    },
                )
            }
            public_wire::NamedProcessStreamRequest::Read {
                stream: public_wire::ExecStream::Stdout,
                offset,
                max_len,
                wait,
                timeout_ms,
            } => d2bd_runtime::shell_backend::ShellTerminalOp::ReadOutput(
                d2b_contracts_control::terminal_wire::TerminalReadOutput {
                    session: session.clone(),
                    stream: d2b_contracts_control::terminal_wire::TerminalStream::Stdout,
                    offset,
                    max_len,
                    wait,
                    timeout_ms,
                },
            ),
            public_wire::NamedProcessStreamRequest::Read { .. }
            | public_wire::NamedProcessStreamRequest::Signal { .. }
            | public_wire::NamedProcessStreamRequest::Wait { .. } => {
                let _ =
                    write_named_process_stream_error(&stream, request_id, shell_protocol_failed());
                continue;
            }
            public_wire::NamedProcessStreamRequest::Resize {
                control_seq,
                rows,
                cols,
            } => {
                if control_seq == 0 || control_seq <= control_sequence {
                    let _ = write_named_process_stream_error(
                        &stream,
                        request_id,
                        shell_failed(
                            d2bd_runtime::typed_error::GuestControlShellErrorKind::StaleSession,
                        ),
                    );
                    continue;
                }
                control_sequence = control_seq.saturating_sub(1);
                d2bd_runtime::shell_backend::ShellTerminalOp::Resize(
                    d2b_contracts_control::terminal_wire::TerminalResize {
                        session: session.clone(),
                        op_id: control_seq,
                        rows,
                        cols,
                    },
                )
            }
            public_wire::NamedProcessStreamRequest::Close
            | public_wire::NamedProcessStreamRequest::Cancel => unreachable!(),
        };
        let response = match established
            .backend
            .handle_op(rt.handle(), &mut control_sequence, op)
        {
            Ok(Some(d2bd_runtime::shell_backend::ShellTerminalResponse::WriteStdin(result))) => {
                if close_stdin {
                    public_wire::NamedProcessStreamResponse::Closed(public_wire::ExecCloseResult {
                        stdin_closed: result.stdin_closed,
                    })
                } else {
                    public_wire::NamedProcessStreamResponse::Stdin(
                        public_wire::ExecWriteStdinResult {
                            accepted_len: result.accepted_len,
                            next_offset: result.next_offset,
                            backpressured: result.backpressured,
                            stdin_closed: result.stdin_closed,
                        },
                    )
                }
            }
            Ok(Some(d2bd_runtime::shell_backend::ShellTerminalResponse::ReadOutput(result))) => {
                public_wire::NamedProcessStreamResponse::Output(public_wire::ExecReadOutputResult {
                    data_base64: result.data_base64,
                    next_offset: result.next_offset,
                    eof: result.eof,
                    dropped_bytes: result.dropped_bytes,
                    truncated: result.truncated,
                    timed_out: result.timed_out,
                })
            }
            Ok(Some(d2bd_runtime::shell_backend::ShellTerminalResponse::Delivered)) => {
                public_wire::NamedProcessStreamResponse::Delivered(public_wire::ExecControlResult {
                    delivered: true,
                })
            }
            Ok(None) => break,
            Err(error) => {
                let _ = write_named_process_stream_error(&stream, request_id, error);
                continue;
            }
        };
        let response = public_wire::NamedProcessStreamResponseFrame::new(request_id, response);
        if write_json_frame(
            &stream,
            &serde_json::to_value(response).unwrap_or_else(|_| json!({})),
        )
        .is_err()
        {
            break;
        }
    }
    let close_result = close_result.unwrap_or_else(|| {
        d2bd_runtime::shell_backend::best_effort_cancel(
            established.backend.as_ref(),
            rt.handle(),
            &mut control_sequence,
        )
    });
    emit_shell_close_audit(
        &state,
        peer.uid,
        &established,
        close_result,
        &owner_shell_ref_digest,
    );
    shell_metric_for_provider(&state, established.provider, "close", "closed", "none");
}

async fn establish_shell_backend(
    state: &ServerState,
    peer_uid: u32,
    caller_role: BrokerCallerRole,
    attach: &public_wire::ShellAttachArgs,
    component_session_driver: Option<d2b_session::SessionDriverHandle>,
) -> Result<d2bd_runtime::shell_backend::EstablishedShell, TypedError> {
    use workload_dispatch::WorkloadRoute;

    let resolved = resolve_shell_target(state, &attach.vm)?;

    match resolved.route {
        WorkloadRoute::LocalVm { vm } => {
            let Some(driver) = component_session_driver else {
                let _ = (state, peer_uid, caller_role, attach);
                return Err(TypedError::RuntimeCapabilityUnsupported {
                    vm,
                    runtime_kind: "component-session".to_owned(),
                    capability: "persistent-shell".to_owned(),
                    verb: "shell".to_owned(),
                });
            };
            let public_session = new_public_shell_session_handle()?;
            let resolved_name = attach
                .name
                .clone()
                .unwrap_or_else(|| public_wire::ShellName::new("primary").expect("valid name"));
            let backend = d2bd_runtime::shell_backend::ComponentSessionShellBackend::open(
                driver,
                next_component_session_stream_number(),
                public_session.clone(),
                resolved_name.clone(),
            )
            .await
            .map_err(|_| shell_transport_failed())?;
            Ok(d2bd_runtime::shell_backend::EstablishedShell {
                backend: Arc::new(backend),
                attach: public_wire::ShellAttachResult {
                    session: public_session,
                    resolved_name,
                    state: public_wire::ShellSessionState::Attached,
                    force_evicted: false,
                },
                target: vm,
                provider: d2bd_runtime::shell_backend::ShellProvider::GuestControl,
                operation_digest: None,
                initial_control_sequence: 0,
            })
        }
        WorkloadRoute::UnsafeLocal => {
            let identity = resolved.identity.ok_or_else(|| {
                d2bd_runtime::shell_backend::unsafe_shell_failed(
                    d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                )
            })?;
            let policy = resolved.policy.ok_or_else(|| {
                d2bd_runtime::shell_backend::unsafe_shell_failed(
                    d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                )
            })?;
            let operation_id = new_internal_shell_operation_id()?;
            let operation_digest = shell_ref_digest(&[operation_id.as_str()]);
            emit_provider_shell_audit(
                state,
                ProviderShellAudit {
                    target: &identity.canonical_target.to_canonical(),
                    peer_uid,
                    provider: d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                    action: d2bd_runtime::daemon_audit::ShellAuditAction::Create,
                    result: d2bd_runtime::daemon_audit::ShellAuditResult::Requested,
                    force: None,
                    operation_digest: Some(operation_digest.clone()),
                    session_digest: None,
                },
            );
            shell_metric_for_provider(
                state,
                d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                "create",
                "requested",
                "none",
            );
            let request_id = next_internal_shell_request_id();
            let request = d2b_contracts_control::unsafe_local_wire::HelperShellRequest::Attach {
                request_id,
                operation_id: operation_id.clone(),
                workload: identity.clone(),
                policy,
                name: attach.name.clone(),
                force: attach.force,
                initial_terminal_size: attach.initial_terminal_size,
            };
            let reply = state
                .unsafe_local_helpers
                .dispatch_shell(peer_uid, request)
                .map_err(map_shell_helper_registry_error)?;
            let d2bd_runtime::unsafe_local_helper::HelperShellReply::Terminal { ready, fd } = reply
            else {
                return Err(d2bd_runtime::shell_backend::unsafe_shell_failed(
                    d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                ));
            };
            let public_session = new_public_shell_session_handle()?;
            let terminal = d2bd_runtime::unsafe_local_terminal::UnsafeLocalTerminalClient::new(fd)
                .map_err(|_| {
                    d2bd_runtime::shell_backend::unsafe_shell_failed(
                        d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
                    )
                })?;
            let resolved_name = ready.result.resolved_name;
            let backend = d2bd_runtime::shell_backend::UnsafeLocalShellBackend::new(
                public_session.clone(),
                resolved_name.clone(),
                terminal,
            );
            Ok(d2bd_runtime::shell_backend::EstablishedShell {
                backend: Arc::new(backend),
                attach: public_wire::ShellAttachResult {
                    session: public_session,
                    resolved_name,
                    state: ready.result.state,
                    force_evicted: ready.result.force_evicted,
                },
                target: identity.canonical_target.to_canonical(),
                provider: d2bd_runtime::shell_backend::ShellProvider::UnsafeLocal,
                operation_digest: Some(operation_digest),
                initial_control_sequence: 0,
            })
        }
        WorkloadRoute::CapabilityUnavailable { provider } => {
            Err(TypedError::RuntimeCapabilityUnsupported {
                vm: attach.vm.clone(),
                runtime_kind: workload_provider_label(provider).to_owned(),
                capability: "persistent-shell".to_owned(),
                verb: "shell".to_owned(),
            })
        }
    }
}

fn resolve_shell_target(
    state: &ServerState,
    target: &str,
) -> Result<workload_dispatch::ResolvedShell, TypedError> {
    use workload_dispatch::{CatalogError, ResolvedShell, WorkloadCatalog, WorkloadRoute};

    let resolver = load_bundle_resolver(state)?;
    match WorkloadCatalog::from_resolver(&resolver) {
        Ok(catalog) => catalog
            .resolve_shell(resolver.unsafe_local_workloads.as_ref(), target)
            .map_err(|error| map_shell_catalog_error(error, target)),
        Err(CatalogError::ArtifactsUnavailable) if !target.ends_with(".d2b") => Ok(ResolvedShell {
            identity: None,
            route: WorkloadRoute::LocalVm {
                vm: target.to_owned(),
            },
            policy: None,
        }),
        Err(error) => Err(map_shell_catalog_error(error, target)),
    }
}

fn map_shell_catalog_error(error: workload_dispatch::CatalogError, target: &str) -> TypedError {
    use workload_dispatch::CatalogError;
    match error {
        CatalogError::TargetNotFound => TypedError::WorkloadTargetNotFound {
            target: target.to_owned(),
        },
        CatalogError::AliasConflict => TypedError::WorkloadAliasConflict {
            workload_id: target.to_owned(),
            detail: "multiple configured workloads share this short id".to_owned(),
        },
        CatalogError::ShellCapabilityUnavailable => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(
                d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::ShellUnavailable,
            )
        }
        CatalogError::ArtifactsUnavailable
        | CatalogError::ConfiguredItemMissing
        | CatalogError::ConfiguredItemMismatch => d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Protocol,
        ),
        CatalogError::LauncherDisabled
        | CatalogError::ItemNotFound
        | CatalogError::OperationConflict
        | CatalogError::OperationInProgress => d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Internal,
        ),
    }
}

fn next_internal_helper_request_id() -> u64 {
    static REQUEST_ID: AtomicU64 = AtomicU64::new(1);
    loop {
        let request_id = REQUEST_ID.fetch_add(1, Ordering::Relaxed);
        if request_id != 0 {
            return request_id;
        }
    }
}

fn next_internal_shell_request_id() -> u64 {
    next_internal_helper_request_id()
}

fn new_internal_shell_operation_id() -> Result<d2b_realm_core::OperationId, TypedError> {
    let mut bytes = [0u8; 16];
    getrandom::getrandom(&mut bytes).map_err(|_| {
        d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Internal,
        )
    })?;
    d2b_realm_core::OperationId::parse(format!("shell-{}", hex_bytes(&bytes))).map_err(|_| {
        d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Internal,
        )
    })
}

fn new_public_shell_session_handle() -> Result<String, TypedError> {
    let mut bytes = [0u8; 16];
    getrandom::getrandom(&mut bytes).map_err(|_| {
        d2bd_runtime::shell_backend::unsafe_shell_failed(
            d2bd_runtime::typed_error::UnsafeLocalShellErrorKind::Internal,
        )
    })?;
    Ok(format!("shell-{}", hex_bytes(&bytes)))
}

fn map_shell_helper_registry_error(
    error: d2bd_runtime::unsafe_local_helper::HelperRegistryError,
) -> TypedError {
    use d2bd_runtime::typed_error::UnsafeLocalShellErrorKind as UnsafeKind;
    use d2bd_runtime::unsafe_local_helper::HelperRegistryError as H;
    match error {
        H::HelperUnavailable | H::Io => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::HelperUnavailable)
        }
        H::HelperStale | H::GenerationSuperseded => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::HelperStale)
        }
        H::QueueFull | H::OperationInProgress => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::QueueFull)
        }
        H::Timeout => d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::Timeout),
        H::OperationIdConflict => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::OperationConflict)
        }
        H::OperationRejected(code) => d2bd_runtime::shell_backend::map_helper_failure(code),
        H::InvalidFrame
        | H::InvalidRequest
        | H::FrameTooLarge
        | H::ProtocolMismatch
        | H::RequestCorrelationMismatch
        | H::InvalidTerminalFd
        | H::SocketBufferTooSmall
        | H::SnapshotTooLarge => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::Protocol)
        }
        H::UnauthorizedPeer | H::InvalidPeer => {
            d2bd_runtime::shell_backend::unsafe_shell_failed(UnsafeKind::Internal)
        }
    }
}

#[cfg(test)]
#[allow(dead_code)]
async fn establish_guest_shell_owner_async(
    state: &ServerState,
    attach: &public_wire::ShellAttachArgs,
    caller_role: BrokerCallerRole,
) -> Result<
    (
        Arc<d2bd_runtime::guest_control_health::TtrpcGuestControlClient>,
        String,
        pb::ShellAttachResponse,
    ),
    TypedError,
> {
    ensure_vm_runtime_capability(
        state,
        &attach.vm,
        RuntimeCapabilityGate::GuestControl,
        "shell",
    )?;
    let resolver = load_bundle_resolver(state)?;
    let params = resolve_guest_control_probe_params(state, &resolver, &attach.vm)
        .map_err(|_| shell_transport_failed())?;
    let broker_path = broker_socket_path(state);
    let budget = d2bd_runtime::guest_control_health::AttemptBudget::from_now(
        SHELL_MANAGEMENT_TIMEOUT,
        guest_control_bridge::GUEST_CONTROL_ATTEMPT_CAP,
    );
    let signer = guest_control_bridge::BrokerSigner::with_caller_role(
        broker_path,
        budget,
        caller_role.clone(),
    );
    let nonce = guest_control_bridge::host_nonce().map_err(|_| shell_transport_failed())?;
    let client = guest_control_bridge::connect_and_build_client(&params, budget)
        .map_err(map_shell_health_error)?;
    let evidence = d2bd_runtime::guest_control_health::probe_guest_control_health(
        &params.vm_id,
        Some(guest_control_bridge::VMADDR_CID_HOST),
        nonce,
        &client,
        &signer,
    )
    .await
    .map_err(map_shell_health_error)?;
    if !guest_advertises_capability(
        &evidence.health.capabilities,
        pb::GuestCapability::GUEST_CAPABILITY_SHELL_ATTACHED,
    ) {
        return Err(shell_capability_failed());
    }
    if attach.force
        && !guest_advertises_capability(
            &evidence.health.capabilities,
            pb::GuestCapability::GUEST_CAPABILITY_SHELL_FORCE_ATTACH,
        )
    {
        return Err(shell_capability_failed());
    }
    let mut request = pb::ShellAttachRequest::new();
    request.metadata = protobuf::MessageField::some(shell_request_metadata(&params.vm_id));
    request.name = attach.name.as_ref().map(|name| name.as_str().to_owned());
    request.force = attach.force;
    let mut size = pb::TerminalSize::new();
    size.rows = attach.initial_terminal_size.rows;
    size.cols = attach.initial_terminal_size.cols;
    request.initial_terminal_size = protobuf::MessageField::some(size);
    let response: pb::ShellAttachResponse = client
        .unary_with_timeout("ShellAttach", request, SHELL_MANAGEMENT_TIMEOUT)
        .await
        .map_err(map_shell_health_error)?;
    shell_error_to_typed(response.error.as_ref())?;
    Ok((Arc::new(client), evidence.guest_boot_id, response))
}

