fn dispatch_broker_host_prepare_as(
    state: &ServerState,
    request: public_wire::HostPrepareRequest,
    caller_role: BrokerCallerRole,
) -> Result<Value, TypedError> {
    const VERB: &str = "host prepare";

    if let Some(response) = mutating_verb_preflight(VERB, &request.flags, None) {
        return Ok(response);
    }
    let dispatch_broker_ack_request =
        |state: &ServerState, verb: &str, op_name: &str, request: BrokerRequest| {
            dispatch_broker_ack_request_as(state, verb, op_name, request, caller_role.clone())
        };

    let host = load_host_artifact(state)?;
    if let Err(response) = dispatch_broker_ack_request(
        state,
        VERB,
        "ApplyNftables",
        BrokerRequest::ApplyNftables(BrokerApplyNftablesRequest {
            bundle_nft_intent_ref: BundleOpId::new(intent_id_nft_host()),
            scope_id: ScopeId::new("host"),
            desired_hash: None,
            destroy: false,
            tracing_span_id: None,
        }),
    ) {
        return Ok(response);
    }

    let mut route_ops = 0usize;
    let mut sysctl_ops = 0usize;
    for env in &host.environments {
        let scope_id = ScopeId::new(format!("env:{}", env.env));
        for (idx, _) in env.net_vm_forward_blocklist.iter().enumerate() {
            route_ops += 1;
            if let Err(response) = dispatch_broker_ack_request(
                state,
                VERB,
                "ApplyRoute",
                BrokerRequest::ApplyRoute(BrokerApplyRouteRequest {
                    bundle_route_intent_ref: BundleOpId::new(intent_id_route_env(&env.env, idx)),
                    scope_id: scope_id.clone(),
                    destroy: false,
                    tracing_span_id: None,
                }),
            ) {
                return Ok(response);
            }
        }
        for entry in &env.ipv6_sysctls {
            for key in ipv6_sysctl_short_keys(entry) {
                sysctl_ops += 1;
                if let Err(response) = dispatch_broker_ack_request(
                    state,
                    VERB,
                    "ApplySysctl",
                    BrokerRequest::ApplySysctl(BrokerApplySysctlRequest {
                        bundle_sysctl_intent_ref: BundleOpId::new(intent_id_sysctl(
                            &env.env,
                            entry.if_name.as_str(),
                            key,
                        )),
                        scope_id: scope_id.clone(),
                        destroy: false,
                        tracing_span_id: None,
                    }),
                ) {
                    return Ok(response);
                }
            }
        }
    }
    if let Err(response) = dispatch_broker_ack_request(
        state,
        VERB,
        "UpdateHostsFile",
        BrokerRequest::UpdateHostsFile(BrokerUpdateHostsFileRequest {
            bundle_hosts_intent_ref: BundleOpId::new(intent_id_hosts_host()),
            destroy: false,
            tracing_span_id: None,
        }),
    ) {
        return Ok(response);
    }
    let resolver = load_bundle_resolver(state)?;
    let generation =
        resolver
            .installed_generation_identity()
            .ok_or(TypedError::InternalBrokerUnavailable {
                path: broker_socket_path(state),
                detail: "installed generation unavailable for Network effect context".to_owned(),
            })?;
    let context = d2b_provider_network_local::broker::NetworkEffectContext::for_host_nm(
        ScopeId::new("host"),
        BundleOpId::new(intent_id_nm_unmanaged_host()),
        d2b_contracts_resource::v3::ResourceBundleGenerationId::parse(generation.as_str())
            .map_err(|_| TypedError::InternalBrokerUnavailable {
                path: broker_socket_path(state),
                detail: "installed generation invalid for Network effect context".to_owned(),
            })?,
    );
    let port = network_effect_port::production_port(state, caller_role.clone(), context.clone());
    let broker = port.into_broker();
    if let Err(error) =
        d2b_provider_network_local::broker::NetworkBroker::apply_nm_unmanaged(&broker, &context)
    {
        return Ok(broker_failure_response(
            VERB,
            format!("NetworkManager effect refused ({})", error.code()),
            "Regenerate the trusted network bundle and retry host prepare.".to_owned(),
            None,
        ));
    }

    Ok(applied_response(
        VERB,
        format!(
            "host prepare: applied 1 nft + {route_ops} route + {sysctl_ops} sysctl + 1 hosts + 1 nm-unmanaged ops"
        ),
    ))
}

