    #[test]
    fn public_lifecycle_status_probe_does_not_use_shutdown_timeout() {
        let (state, _dir) = test_state();
        state
            .pidfd_table
            .register(
                "vm-a".to_owned(),
                VM_RUNNER_ROLE_ID.to_owned(),
                current_process_entry(),
            )
            .expect("register ch runner");
        let socket_dir = tempfile::tempdir().expect("socket dir");
        let socket_path = socket_dir.path().join("ch-api.sock");
        let listener =
            std::os::unix::net::UnixListener::bind(&socket_path).expect("bind hanging ch socket");
        let _server = std::thread::spawn(move || {
            if let Ok((_stream, _addr)) = listener.accept() {
                std::thread::sleep(Duration::from_secs(2));
            }
        });
        let manifest_entry = json!({
            "stateDir": "/nonexistent/d2b-public-status-test",
            "apiSocket": socket_path,
            "runtime": {
                "provider": {
                    "driver": "cloud-hypervisor"
                }
            }
        });

        let started = Instant::now();
        let lifecycle = public_vm_lifecycle(&state, "vm-a", &manifest_entry, None);

        assert_eq!(lifecycle_state(&lifecycle), "Running");
        assert!(
            started.elapsed() < Duration::from_secs(1),
            "status/list provider probes must not inherit the graceful shutdown API timeout"
        );
    }

    #[test]
    fn public_lifecycle_reports_running_for_qemu_media_runner() {
        let (state, _dir) = test_state();
        state
            .pidfd_table
            .register(
                "installer".to_owned(),
                RunnerRole::QemuMedia.as_str().to_owned(),
                current_process_entry(),
            )
            .expect("register qemu media runner");
        let manifest_entry = qemu_media_manifest_entry();
        let dag = qemu_media_process_dag();
        let lifecycle = public_vm_lifecycle(&state, "installer", &manifest_entry, Some(&dag));
        let services = d2bd_runtime::public_projection::public_service_states(
            &state.pidfd_table,
            "installer",
            &manifest_entry,
            Some(&dag),
        );
        let runtime = public_runtime_summary(&lifecycle, &manifest_entry);

        assert_eq!(lifecycle_state(&lifecycle), "Running");
        assert_eq!(
            runtime.get("kind").and_then(Value::as_str),
            Some("qemu-media")
        );
        assert_eq!(
            services.get("microvm").and_then(Value::as_str),
            Some("unsupported")
        );
        assert_eq!(
            services.get("qemuMedia").and_then(Value::as_str),
            Some("running")
        );
        assert_eq!(
            services.get("virtiofsd").and_then(Value::as_str),
            Some("unsupported")
        );
        assert_eq!(
            public_service_capabilities(&services),
            vec!["d2b".to_owned(), "qemu-media".to_owned()]
        );
    }

    #[test]
    fn public_qemu_media_capability_projection_is_stable() {
        let defaulted = qemu_media_default_capability_manifest_entry();
        assert_eq!(
            public_runtime_capabilities(&defaulted),
            vec!["display", "lifecycle", "usb-hotplug"]
        );
        assert_eq!(
            public_unsupported_capabilities(&defaulted),
            vec![
                "config-sync",
                "exec",
                "guest-control",
                "in-guest-observability",
                "keys",
                "ssh",
                "store-sync"
            ]
        );

        let explicit = qemu_media_manifest_entry();
        assert_eq!(public_runtime_capabilities(&explicit), vec!["usb-hotplug"]);
        assert_eq!(
            public_unsupported_capabilities(&explicit),
            vec![
                "config-sync",
                "exec",
                "guest-control",
                "keys",
                "ssh",
                "store-sync"
            ]
        );
    }

    #[test]
    fn qemu_media_status_reports_manual_runtime_and_missing_registry() {
        let root = tempfile::tempdir().expect("registry root");
        let (state, _dir) = test_state();
        let manifest_entry = qemu_media_manifest_entry();
        let dag = qemu_media_process_dag();
        let services = d2bd_runtime::public_projection::public_service_states(
            &state.pidfd_table,
            "installer",
            &manifest_entry,
            Some(&dag),
        );
        let qemu = public_qemu_media_status(
            &state,
            "installer",
            Some("qemu-media"),
            None,
            Some(&dag),
            &services,
        )
        .expect("qemu media status");

        assert_eq!(
            qemu.pointer("/firmwareMode").and_then(Value::as_str),
            Some("none")
        );
        assert_eq!(
            qemu.pointer("/runner/role").and_then(Value::as_str),
            Some("qemu-media")
        );
        assert_eq!(
            qemu.pointer("/runner/qmpSocket").and_then(Value::as_str),
            None
        );
        let source_status =
            qemu_media_source_status(&root.path().display().to_string(), &qemu_media_source());
        assert_eq!(
            source_status.pointer("/slot").and_then(Value::as_str),
            Some("boot")
        );
        assert_eq!(
            source_status
                .pointer("/registry/state")
                .and_then(Value::as_str),
            Some("missing")
        );
        assert!(
            source_status
                .pointer("/registry/remediation")
                .and_then(Value::as_str)
                .is_some_and(|text| text.contains("installer-usb"))
        );
        assert!(
            source_status
                .pointer("/registry/remediation")
                .and_then(Value::as_str)
                .is_some_and(|text| text.contains("d2b usb probe") && !text.contains("usb enroll"))
        );
    }

