        let (timeout_ms, deadline) = super::shell_poll_timeout(999_000, true);
        assert_eq!(timeout_ms, super::SHELL_POLL_CAP.as_millis() as u64);
        assert_eq!(deadline, super::SHELL_POLL_CAP + super::SHELL_POLL_SLACK);

